"use strict";
// Preview process manager: one dev server (or built-in static server) per project.

const { spawn } = require("child_process");
const fs = require("fs");
const net = require("net");
const path = require("path");
const { createStaticServer } = require("./static");

const LOG_LINES = 200;

function probePort(port, timeoutMs = 400) {
  const tryHost = (host) =>
    new Promise((resolve) => {
      const sock = net.connect({ host, port });
      const finish = (ok) => {
        sock.destroy();
        resolve(ok);
      };
      sock.setTimeout(timeoutMs, () => finish(false));
      sock.once("connect", () => finish(true));
      sock.once("error", () => finish(false));
    });
  return tryHost("127.0.0.1").then((ok) => ok || tryHost("::1"));
}

/** Find pids (same uid) with a LISTEN socket on `port`, via /proc. Linux only. */
function listenerPids(port) {
  const inodes = new Set();
  const hex = port.toString(16).toUpperCase().padStart(4, "0");
  for (const f of ["/proc/net/tcp", "/proc/net/tcp6"]) {
    let txt;
    try {
      txt = fs.readFileSync(f, "utf8");
    } catch {
      continue;
    }
    for (const line of txt.split("\n").slice(1)) {
      const cols = line.trim().split(/\s+/);
      if (cols.length < 10) continue;
      const localPort = cols[1].split(":").pop();
      if (localPort === hex && cols[3] === "0A") inodes.add(cols[9]);
    }
  }
  const pids = new Set();
  if (!inodes.size) return [];
  let procs = [];
  try {
    procs = fs.readdirSync("/proc").filter((d) => /^\d+$/.test(d));
  } catch {
    return [];
  }
  for (const pid of procs) {
    let fds;
    try {
      fds = fs.readdirSync(`/proc/${pid}/fd`);
    } catch {
      continue;
    }
    for (const fd of fds) {
      try {
        const l = fs.readlinkSync(`/proc/${pid}/fd/${fd}`);
        const m = /^socket:\[(\d+)\]$/.exec(l);
        if (m && inodes.has(m[1])) {
          pids.add(Number(pid));
          break;
        }
      } catch {
        /* ignore */
      }
    }
  }
  return [...pids];
}

function pgidOf(pid) {
  try {
    const stat = fs.readFileSync(`/proc/${pid}/stat`, "utf8");
    const after = stat.slice(stat.lastIndexOf(")") + 2).split(" ");
    return Number(after[2]); // state ppid pgrp
  } catch {
    return null;
  }
}

function readJSON(file) {
  try {
    return JSON.parse(fs.readFileSync(file, "utf8"));
  } catch {
    return null;
  }
}

/**
 * Decide how to run a project's preview.
 * @returns {{kind:'process', command:string} | {kind:'static', root:string} | {error:string}}
 */
function detectCommand(dir, slug, port) {
  const base = `/preview/${slug}/`; // slug = preview key (<slug> or <slug>--<worktree>)
  const pkg = readJSON(path.join(dir, "package.json"));
  if (pkg) {
    const scripts = pkg.scripts || {};
    const deps = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };
    const install = fs.existsSync(path.join(dir, "node_modules")) ? "" : "npm install --no-audit --no-fund && ";
    if (scripts.dev) {
      if (deps.vite || /\bvite\b/.test(scripts.dev)) {
        return { kind: "process", command: `${install}npm run dev -- --host 0.0.0.0 --port ${port} --strictPort --base ${base}` };
      }
      if (deps.next || /\bnext\b/.test(scripts.dev)) {
        return { kind: "process", command: `${install}npx next dev -p ${port} -H 0.0.0.0` };
      }
      return { kind: "process", command: `${install}npm run dev` };
    }
    if (scripts.start) return { kind: "process", command: `${install}npm start` };
  }
  for (const sub of ["", "dist", "build", "public", "out"]) {
    const root = path.join(dir, sub);
    if (fs.existsSync(path.join(root, "index.html"))) return { kind: "static", root };
  }
  return { error: "Could not detect a preview command (no package.json dev/start script and no index.html). Pass `command`." };
}

class PreviewManager {
  constructor(config) {
    this.config = {
      projectsDir: "/workspace/projects",
      portMin: 4100,
      portMax: 4199,
      env: process.env,
      allowedHost: "claudebox",
      log: () => {},
      ...config,
    };
    this.previews = new Map(); // preview key -> record
  }

  /** Preview key + directory: main = <slug> in <projectsDir>/<slug>; branch = <slug>--<worktree> in .branches/<slug>/<worktree>. */
  target(slug, worktree) {
    if (!worktree) return { key: slug, dir: path.join(this.config.projectsDir, slug) };
    return { key: `${slug}--${worktree}`, dir: path.join(this.config.projectsDir, ".branches", slug, worktree) };
  }

  _alive(rec) {
    return !!rec && rec.alive;
  }

  _appendLog(rec, text) {
    rec.partial += text;
    const lines = rec.partial.split(/\r?\n/);
    rec.partial = lines.pop();
    for (const l of lines) rec.logs.push(l);
    if (rec.partial.length > 4000) {
      rec.logs.push(rec.partial);
      rec.partial = "";
    }
    if (rec.logs.length > LOG_LINES) rec.logs.splice(0, rec.logs.length - LOG_LINES);
  }

  _env(slug, port) {
    const env = { ...this.config.env };
    for (const k of ["CLAUDEBOX_API_KEY", "CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY"]) delete env[k];
    Object.assign(env, {
      PORT: String(port),
      HOST: "0.0.0.0",
      BASE_PATH: `/preview/${slug}/`,
      BROWSER: "none",
      __VITE_ADDITIONAL_SERVER_ALLOWED_HOSTS: this.config.allowedHost,
    });
    return env;
  }

  async start({ projectSlug, worktree, port, command }) {
    const c = this.config;
    const { key: slug, dir } = this.target(projectSlug, worktree);
    if (worktree && !fs.existsSync(dir)) return { status: 404, body: { error: `Branch worktree '${worktree}' not found` } };
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    if (!Number.isInteger(port) || port < c.portMin || port > c.portMax) {
      return { status: 400, body: { error: `port must be an integer in ${c.portMin}-${c.portMax}` } };
    }
    for (const [other, rec] of this.previews) {
      if (other !== slug && this._alive(rec) && rec.port === port) {
        return { status: 409, body: { error: `Port ${port} is used by preview of '${other}'` } };
      }
    }
    if (this._alive(this.previews.get(slug))) await this.stop({ projectSlug: slug });
    if (await probePort(port)) {
      // Something (usually a dev server Claude started via Bash) already serves this port: adopt it.
      return { status: 200, body: { ...(await this.status(slug, port)), adopted: true } };
    }

    let plan;
    if (command != null && command !== "") {
      if (typeof command !== "string" || command.length > 4000) return { status: 400, body: { error: "Invalid command" } };
      plan = { kind: "process", command };
    } else {
      plan = detectCommand(dir, slug, port);
      if (plan.error) return { status: 422, body: { error: plan.error } };
    }

    const rec = {
      slug, port, kind: plan.kind, command: plan.kind === "static" ? `builtin-static ${plan.root}` : plan.command,
      pid: null, proc: null, server: null, alive: false, startedAt: Date.now(), exitCode: null, exitedAt: null,
      logs: [], partial: "",
    };
    this.previews.set(slug, rec);

    if (plan.kind === "static") {
      const server = createStaticServer({
        root: plan.root,
        prefix: `/preview/${slug}/`,
        onLog: (l) => this._appendLog(rec, l + "\n"),
      });
      const sockets = new Set();
      server.on("connection", (s) => {
        sockets.add(s);
        s.on("close", () => sockets.delete(s));
      });
      try {
        await new Promise((resolve, reject) => {
          server.once("error", reject);
          server.listen(port, "0.0.0.0", resolve);
        });
      } catch (err) {
        rec.exitCode = 1;
        this._appendLog(rec, `static server failed: ${err.message}\n`);
        return { status: 500, body: { error: err.message, ...(await this.status(slug)) } };
      }
      rec.server = server;
      rec.sockets = sockets;
      rec.alive = true;
      rec.pid = process.pid;
      this._appendLog(rec, `serving ${plan.root} at http://0.0.0.0:${port}/preview/${slug}/\n`);
      c.log("info", "preview started", { slug, port, kind: "static" });
      return { status: 200, body: await this.status(slug) };
    }

    const proc = spawn("bash", ["-c", plan.command], {
      cwd: dir,
      env: this._env(slug, port),
      stdio: ["ignore", "pipe", "pipe"],
      detached: true,
    });
    rec.proc = proc;
    rec.pid = proc.pid;
    rec.alive = true;
    this._appendLog(rec, `$ ${plan.command}\n`);
    proc.stdout.setEncoding("utf8");
    proc.stderr.setEncoding("utf8");
    proc.stdout.on("data", (d) => this._appendLog(rec, d));
    proc.stderr.on("data", (d) => this._appendLog(rec, d));
    proc.on("error", (err) => {
      this._appendLog(rec, `spawn error: ${err.message}\n`);
      rec.alive = false;
    });
    proc.on("exit", (code, signal) => {
      rec.alive = false;
      rec.exitCode = code;
      rec.exitedAt = Date.now();
      if (rec.partial) {
        rec.logs.push(rec.partial);
        rec.partial = "";
      }
      this._appendLog(rec, `[process exited code=${code} signal=${signal || ""}]\n`);
      c.log("info", "preview exited", { slug, code, signal });
    });
    c.log("info", "preview started", { slug, port, pid: proc.pid, command: plan.command });
    return { status: 200, body: await this.status(slug) };
  }

  async stop({ projectSlug, worktree, port }) {
    const slug = this.target(projectSlug, worktree).key;
    const rec = this.previews.get(slug);
    const targetPort = port || rec?.port || null;
    let stopped = false;
    if (rec && rec.alive) {
      if (rec.kind === "static" && rec.server) {
        await new Promise((resolve) => {
          rec.server.close(() => resolve());
          for (const s of rec.sockets || []) s.destroy();
        });
        rec.alive = false;
        rec.exitedAt = Date.now();
        this._appendLog(rec, "[static server stopped]\n");
      } else if (rec.proc) {
        const pid = rec.pid;
        const kill = (sig) => {
          try {
            process.kill(-pid, sig);
          } catch {
            try {
              process.kill(pid, sig);
            } catch {
              /* gone */
            }
          }
        };
        kill("SIGTERM");
        const exited = await new Promise((resolve) => {
          if (!rec.alive) return resolve(true);
          const t = setTimeout(() => resolve(false), 3000);
          rec.proc.once("exit", () => {
            clearTimeout(t);
            resolve(true);
          });
        });
        if (!exited) kill("SIGKILL");
        // also kill leftovers of the group even if leader exited
        try {
          process.kill(-pid, "SIGKILL");
        } catch {
          /* none */
        }
      }
      stopped = true;
    }
    // Something else (e.g. a server Claude started via Bash) still listening on the port?
    if (targetPort && Number.isInteger(targetPort) && targetPort >= this.config.portMin && targetPort <= this.config.portMax) {
      const ownPgid = pgidOf(process.pid);
      const protectedPgids = new Set(this.config.protectedPgids ? this.config.protectedPgids() : []);
      for (const pid of listenerPids(targetPort)) {
        if (pid === process.pid) continue;
        const pg = pgidOf(pid);
        try {
          if (pg && pg !== ownPgid && pg > 1 && !protectedPgids.has(pg)) process.kill(-pg, "SIGTERM");
          else process.kill(pid, "SIGTERM");
          stopped = true;
          this.config.log("info", "killed external preview listener", { slug, port: targetPort, pid, pgid: pg });
        } catch {
          /* ignore */
        }
      }
    }
    return { stopped, ...(await this.status(slug, targetPort)) };
  }

  async status(slug, port) {
    const rec = this.previews.get(slug) || null;
    const p = port || rec?.port || null;
    const listening = p ? await probePort(p) : false;
    const managed = this._alive(rec);
    return {
      projectSlug: slug,
      running: managed || listening,
      managed,
      listening,
      port: p,
      pid: managed ? rec.pid : null,
      kind: rec?.kind || null,
      command: rec?.command || null,
      startedAt: rec?.startedAt || null,
      exitCode: rec ? rec.exitCode : null,
      logTail: rec ? rec.logs.concat(rec.partial ? [rec.partial] : []).slice(-LOG_LINES) : [],
    };
  }

  async list() {
    const out = [];
    for (const slug of this.previews.keys()) out.push(await this.status(slug));
    return out;
  }

  async stopAll() {
    for (const slug of this.previews.keys()) await this.stop({ projectSlug: slug }).catch(() => {});
  }
}

module.exports = { PreviewManager, detectCommand, probePort, listenerPids };
"use strict";
// Tiny zero-dependency static file server used for static-site previews.
// Serves <root> under <prefix> (e.g. /preview/<slug>/). Requests that do not
// carry the prefix are served relative to root too (for strip-prefix proxies).

const http = require("http");
const fs = require("fs");
const path = require("path");

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".htm": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".cjs": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".map": "application/json; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
  ".md": "text/markdown; charset=utf-8",
  ".xml": "application/xml; charset=utf-8",
  ".svg": "image/svg+xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".webp": "image/webp",
  ".avif": "image/avif",
  ".ico": "image/x-icon",
  ".bmp": "image/bmp",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".ttf": "font/ttf",
  ".otf": "font/otf",
  ".wasm": "application/wasm",
  ".mp4": "video/mp4",
  ".webm": "video/webm",
  ".mp3": "audio/mpeg",
  ".wav": "audio/wav",
  ".ogg": "audio/ogg",
  ".pdf": "application/pdf",
  ".csv": "text/csv; charset=utf-8",
  ".webmanifest": "application/manifest+json",
};

function createStaticServer({ root, prefix, onLog = () => {} }) {
  const rootReal = fs.realpathSync(root);
  const pfx = prefix.endsWith("/") ? prefix : prefix + "/";

  return http.createServer((req, res) => {
    const started = Date.now();
    const done = (status) => onLog(`${req.method} ${req.url} ${status} ${Date.now() - started}ms`);
    if (req.method !== "GET" && req.method !== "HEAD") {
      res.writeHead(405, { Allow: "GET, HEAD" });
      res.end();
      return done(405);
    }
    let pathname;
    try {
      pathname = decodeURIComponent(new URL(req.url, "http://x").pathname);
    } catch {
      res.writeHead(400);
      res.end("Bad request");
      return done(400);
    }
    if (pathname + "/" === pfx) {
      res.writeHead(301, { Location: pfx });
      res.end();
      return done(301);
    }
    let rel = pathname.startsWith(pfx) ? pathname.slice(pfx.length) : pathname.replace(/^\/+/, "");
    if (rel.includes("\0")) {
      res.writeHead(400);
      res.end();
      return done(400);
    }
    let file = path.resolve(rootReal, "." + path.posix.normalize("/" + rel));
    const inside = (p) => p === rootReal || p.startsWith(rootReal + path.sep);
    const send404 = () => {
      res.writeHead(404, { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" });
      res.end("Not found");
      done(404);
    };
    if (!inside(file)) return send404();
    fs.stat(file, (err, st) => {
      if (!err && st.isDirectory()) {
        if (!pathname.endsWith("/")) {
          res.writeHead(301, { Location: pathname + "/" });
          res.end();
          return done(301);
        }
        file = path.join(file, "index.html");
        return serveFile(file);
      }
      if (err) return send404();
      serveFile(file);
    });

    function serveFile(f) {
      fs.realpath(f, (err, real) => {
        if (err || !inside(real)) return send404();
        fs.stat(real, (err2, st) => {
          if (err2 || !st.isFile()) return send404();
          const type = MIME[path.extname(real).toLowerCase()] || "application/octet-stream";
          res.writeHead(200, {
            "Content-Type": type,
            "Content-Length": st.size,
            "Cache-Control": "no-cache",
            "X-Content-Type-Options": "nosniff",
          });
          if (req.method === "HEAD") {
            res.end();
            return done(200);
          }
          const s = fs.createReadStream(real);
          s.on("error", () => res.destroy());
          s.pipe(res);
          res.on("finish", () => done(200));
        });
      });
    }
  });
}

module.exports = { createStaticServer, MIME };

"use strict";
// Run manager for POST /v2/run: queueing, spawning `claude -p` in stream-json mode,
// normalizing events, per-run replay buffer, SSE fan-out, abort.

const { spawn } = require("child_process");
const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const { Normalizer } = require("./normalizer");

const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const WORKTREE_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/;
const RUN_ID_RE = /^[A-Za-z0-9._:-]{1,128}$/;
const SESSION_ID_RE = /^[A-Za-z0-9._-]{1,128}$/;
const MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
const MODES = new Set(["auto", "edit", "plan", "ask"]);
const THINKING = { off: "0", normal: "8000", max: "32000" };
const EFFORTS = new Set(["low", "medium", "high", "xhigh", "max"]);
const AGENT_NAME_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const AGENT_MODEL_RE = /^[A-Za-z0-9._:\[\]\/@-]{1,128}$/;
const TOOL_NAME_RE = /^[A-Za-z0-9_*:().\- ]{1,200}$/;
const AGENTS_INLINE_MAX = 32 * 1024; // larger --agents JSON goes through a temp file
// --autocompact takes the auto-compact *window* (100k-1M); compaction fires at window - 13k
// (CLI: threshold = min(window - 13000, window * PCT_OVERRIDE/100)).
const AUTOCOMPACT_MIN_WINDOW = 100_000;
const AUTOCOMPACT_MAX_WINDOW = 1_000_000;
const AUTOCOMPACT_BUFFER = 13_000;

const EDIT_TOOLS = ["Read", "Edit", "Write", "Glob", "Grep", "Bash", "WebFetch", "WebSearch", "TodoWrite", "NotebookEdit", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList"];
const ASK_TOOLS = ["Read", "Glob", "Grep", "WebFetch", "WebSearch", "TodoWrite", "TaskCreate", "TaskUpdate", "TaskGet", "TaskList"];

const TERMINAL = new Set(["done", "error", "aborted"]);

function isInside(child, parent) {
  const rel = path.relative(parent, child);
  return rel === "" || (!!rel && !rel.startsWith("..") && !path.isAbsolute(rel));
}

/**
 * Build CLI args for a v2 run. `features` comes from parsing `claude --help`.
 */
function buildRunArgs(opts, features = {}, config = {}) {
  const args = ["-p", "--output-format", "stream-json", "--verbose", "--include-partial-messages"];
  if (features.permissionPrompts !== false) args.push("--permission-prompts", "none");
  if (opts.model) args.push("--model", opts.model);
  if (opts.sessionId) args.push("--resume", opts.sessionId);
  if (opts.maxTurns) args.push("--max-turns", String(opts.maxTurns));
  // Effort drives thinking depth and verbosity: keep simple requests cheap.
  const EFFORT = { off: "low", normal: "medium", max: "high" };
  const effort = opts.effort || (features.effort !== false ? EFFORT[opts.thinking || "normal"] : null);
  if (effort) args.push("--effort", effort);
  // Newer CLIs hide thinking text unless asked; summarized display streams readable thinking deltas.
  if (opts.thinking !== "off" && config.thinkingDisplay) args.push("--thinking-display", config.thinkingDisplay);
  if (opts.appendSystemPrompt) args.push("--append-system-prompt", opts.appendSystemPrompt);
  if (config.uploadsDir) args.push("--add-dir", config.uploadsDir);
  const ac = autocompactPlan(opts.autocompactTokens);
  if (ac && features.autocompact !== false) args.push("--autocompact", String(ac.window));
  const hasAgents = !!(opts.agents && Object.keys(opts.agents).length);
  if (hasAgents) args.push("--agents", opts.agentsFile || JSON.stringify(opts.agents));
  if (opts.agent) args.push("--agent", opts.agent);
  if (features.forwardSubagentText && config.forwardSubagentText !== false) args.push("--forward-subagent-text");

  const modes = features.permissionModes || null; // null = unknown, assume all
  const has = (m) => !modes || modes.includes(m);
  switch (opts.mode || "auto") {
    case "auto": {
      const wanted = config.autoPermissionMode || "bypassPermissions";
      args.push("--permission-mode", has(wanted) ? wanted : "bypassPermissions");
      break;
    }
    case "edit":
      // Custom subagents are only useful in edit mode if the Agent tool is pre-approved.
      args.push("--permission-mode", "acceptEdits", "--allowedTools", ...EDIT_TOOLS, ...(hasAgents ? ["Agent"] : []));
      break;
    case "plan":
      args.push("--permission-mode", "plan");
      break;
    case "ask":
      if (has("dontAsk")) args.push("--permission-mode", "dontAsk");
      args.push("--tools", ASK_TOOLS.join(","), "--allowedTools", ...ASK_TOOLS);
      break;
  }
  args.push("--", opts.fullPrompt ?? opts.prompt);
  return args;
}

/**
 * Map a desired auto-compact *threshold* (tokens of context at which compaction fires) to CLI settings.
 * Returns null for "CLI default" (0 / null). Thresholds below 87k use the minimum window (100k) plus
 * CLAUDE_AUTOCOMPACT_PCT_OVERRIDE (percent of the window).
 */
function autocompactPlan(tokens) {
  if (!tokens) return null;
  const want = tokens + AUTOCOMPACT_BUFFER;
  if (want >= AUTOCOMPACT_MIN_WINDOW) return { window: Math.min(AUTOCOMPACT_MAX_WINDOW, want), pct: null };
  return { window: AUTOCOMPACT_MIN_WINDOW, pct: Math.round((tokens / AUTOCOMPACT_MIN_WINDOW) * 1000) / 10 };
}

function validateAgents(raw) {
  if (raw == null) return { agents: null };
  if (typeof raw !== "object" || Array.isArray(raw)) return { error: "Invalid agents (object expected)" };
  const names = Object.keys(raw);
  if (names.length > 100) return { error: "Too many agents" };
  const out = {};
  for (const name of names) {
    const a = raw[name];
    if (!AGENT_NAME_RE.test(name)) return { error: `Invalid agent name: ${name}` };
    if (!a || typeof a !== "object") return { error: `Invalid agent: ${name}` };
    if (typeof a.description !== "string" || !a.description.trim() || a.description.length > 4000) return { error: `Agent ${name}: invalid description` };
    if (typeof a.prompt !== "string" || !a.prompt.trim() || a.prompt.length > 100_000) return { error: `Agent ${name}: invalid prompt` };
    const def = { description: a.description, prompt: a.prompt };
    if (a.tools != null) {
      if (!Array.isArray(a.tools) || a.tools.length > 100 || !a.tools.every((t) => typeof t === "string" && TOOL_NAME_RE.test(t)))
        return { error: `Agent ${name}: invalid tools` };
      def.tools = a.tools;
    }
    if (a.model != null && a.model !== "") {
      if (typeof a.model !== "string" || !AGENT_MODEL_RE.test(a.model)) return { error: `Agent ${name}: invalid model` };
      def.model = a.model;
    }
    out[name] = def;
  }
  return { agents: out };
}

function buildPrompt(prompt, attachments) {
  let out = prompt || "";
  if (attachments && attachments.length) {
    const lines = attachments.map((a) => `[Attached file: ${a} — use Read tool]`);
    out = out ? `${out}\n\n${lines.join("\n")}` : lines.join("\n");
  }
  return out;
}

function buildChildEnv(baseEnv, opts) {
  const env = { ...baseEnv };
  delete env.CLAUDEBOX_API_KEY;
  delete env.PORT; // never leak the API server's PORT to Claude's shell
  if (opts.authToken) {
    if (opts.authToken.startsWith("sk-ant-api")) {
      env.ANTHROPIC_API_KEY = opts.authToken;
      delete env.CLAUDE_CODE_OAUTH_TOKEN;
    } else {
      env.CLAUDE_CODE_OAUTH_TOKEN = opts.authToken;
      delete env.ANTHROPIC_API_KEY;
    }
  }
  if (opts.thinking && THINKING[opts.thinking] !== undefined) env.MAX_THINKING_TOKENS = THINKING[opts.thinking];
  const ac = autocompactPlan(opts.autocompactTokens);
  if (ac && ac.pct != null) env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE = String(ac.pct);
  else delete env.CLAUDE_AUTOCOMPACT_PCT_OVERRIDE;
  if (opts.previewPort) {
    env.PORT = String(opts.previewPort);
    env.HOST = "0.0.0.0";
    env.BASE_PATH = `/preview/${opts.previewKey || opts.projectSlug}/`;
    env.NXEON_PREVIEW_PORT = String(opts.previewPort);
  }
  env.NXEON_PROJECT_SLUG = opts.projectSlug;
  env.NXEON_RUN_ID = opts.runId;
  return env;
}

class RunManager {
  constructor(config) {
    this.config = {
      claudeBin: "claude",
      projectsDir: "/workspace/projects",
      uploadsDir: "/workspace/uploads",
      maxConcurrent: 4,
      retentionMs: 30 * 60 * 1000,
      maxEventsPerRun: 50000,
      killGraceMs: 4000,
      heartbeatMs: 15000,
      previewPortMin: 4100,
      previewPortMax: 4199,
      autoPermissionMode: "bypassPermissions",
      thinkingDisplay: "summarized",
      forwardSubagentText: true,
      log: () => {},
      features: () => ({}),
      env: process.env,
      ...config,
    };
    this.runs = new Map();
    this.queue = [];
    this.running = 0;
    this._gc = setInterval(() => this.gc(), 60 * 1000);
    this._gc.unref();
  }

  close() {
    clearInterval(this._gc);
    for (const run of this.runs.values()) {
      for (const sub of run.subscribers) clearInterval(sub.hb);
      if (run.status === "running") this._kill(run, "SIGKILL");
    }
  }

  /** Validate a /v2/run body. Returns {opts} or {error}. */
  validate(body) {
    const c = this.config;
    if (!body || typeof body !== "object") return { error: "Body must be a JSON object" };
    const runId = body.runId == null ? crypto.randomUUID() : body.runId;
    if (typeof runId !== "string" || !RUN_ID_RE.test(runId)) return { error: "Invalid runId" };
    if (typeof body.prompt !== "string") return { error: "Missing 'prompt' (string)" };
    if (body.prompt.length > 1_000_000) return { error: "Prompt too large" };
    if (typeof body.projectSlug !== "string" || !SLUG_RE.test(body.projectSlug))
      return { error: "Invalid projectSlug (must match ^[a-z0-9][a-z0-9-]{0,47}$)" };
    const sessionId = body.sessionId == null || body.sessionId === "" ? null : body.sessionId;
    if (sessionId !== null && (typeof sessionId !== "string" || !SESSION_ID_RE.test(sessionId))) return { error: "Invalid sessionId" };
    const model = body.model == null || body.model === "" ? null : body.model;
    if (model !== null && (typeof model !== "string" || !MODEL_RE.test(model))) return { error: "Invalid model" };
    const mode = body.mode == null ? "auto" : body.mode;
    if (!MODES.has(mode)) return { error: "Invalid mode (auto|edit|plan|ask)" };
    const thinking = body.thinking == null ? null : body.thinking;
    if (thinking !== null && THINKING[thinking] === undefined) return { error: "Invalid thinking (off|normal|max)" };
    const effort = body.effort == null ? null : body.effort;
    if (effort !== null && !EFFORTS.has(effort)) return { error: "Invalid effort" };
    let maxTurns = null;
    if (body.maxTurns != null) {
      maxTurns = Number(body.maxTurns);
      if (!Number.isInteger(maxTurns) || maxTurns < 1 || maxTurns > 1000) return { error: "Invalid maxTurns" };
    }
    let previewPort = null;
    if (body.previewPort != null) {
      previewPort = Number(body.previewPort);
      if (!Number.isInteger(previewPort) || previewPort < c.previewPortMin || previewPort > c.previewPortMax)
        return { error: `Invalid previewPort (${c.previewPortMin}-${c.previewPortMax})` };
    }
    const appendSystemPrompt = body.appendSystemPrompt == null ? null : body.appendSystemPrompt;
    if (appendSystemPrompt !== null && (typeof appendSystemPrompt !== "string" || appendSystemPrompt.length > 200_000))
      return { error: "Invalid appendSystemPrompt" };
    const authToken = body.authToken == null || body.authToken === "" ? null : body.authToken;
    if (authToken !== null && (typeof authToken !== "string" || authToken.length > 8192 || /[\r\n\0]/.test(authToken)))
      return { error: "Invalid authToken" };

    let autocompactTokens = null;
    if (body.autocompactTokens != null && body.autocompactTokens !== 0) {
      autocompactTokens = Number(body.autocompactTokens);
      if (!Number.isInteger(autocompactTokens) || autocompactTokens < 10_000 || autocompactTokens > AUTOCOMPACT_MAX_WINDOW - AUTOCOMPACT_BUFFER)
        return { error: "Invalid autocompactTokens (0 or 10000-987000)" };
    }
    const va = validateAgents(body.agents);
    if (va.error) return { error: va.error };
    const agents = va.agents && Object.keys(va.agents).length ? va.agents : null;
    const agent = body.agent == null || body.agent === "" ? null : body.agent;
    if (agent !== null && (typeof agent !== "string" || !AGENT_NAME_RE.test(agent))) return { error: "Invalid agent" };
    if (agent !== null && agents && !agents[agent]) return { error: `Lead agent "${agent}" is not in agents` };

    // Branch runs execute in the branch's git worktree (.branches/<slug>/<worktree>); preview key <slug>--<worktree>.
    const worktree = body.worktree == null || body.worktree === "" ? null : body.worktree;
    if (worktree !== null && (typeof worktree !== "string" || !WORKTREE_RE.test(worktree))) return { error: "Invalid worktree" };
    const cwd = worktree ? path.join(c.projectsDir, ".branches", body.projectSlug, worktree) : path.join(c.projectsDir, body.projectSlug);
    if (worktree && !fs.existsSync(cwd)) return { error: `Branch worktree '${worktree}' not found` };
    const previewKey = worktree ? `${body.projectSlug}--${worktree}` : body.projectSlug;
    const attachments = [];
    if (body.attachments != null) {
      if (!Array.isArray(body.attachments) || body.attachments.length > 100) return { error: "Invalid attachments" };
      for (const a of body.attachments) {
        if (typeof a !== "string" || /[\r\n\0]/.test(a)) return { error: "Invalid attachment path" };
        const resolved = path.resolve(a);
        if (!isInside(resolved, c.uploadsDir) && !isInside(resolved, cwd))
          return { error: `Attachment must be under ${c.uploadsDir} or the project dir: ${a}` };
        attachments.push(resolved);
      }
    }
    if (!body.prompt.trim() && !attachments.length) return { error: "Empty prompt" };

    return {
      opts: {
        runId, prompt: body.prompt, projectSlug: body.projectSlug, worktree, previewKey, cwd, sessionId, model, mode, thinking,
        effort, attachments, appendSystemPrompt, maxTurns, previewPort, authToken, autocompactTokens, agents, agent,
        fullPrompt: buildPrompt(body.prompt, attachments),
      },
    };
  }

  get(runId) {
    return this.runs.get(runId) || null;
  }

  create(opts) {
    if (this.runs.has(opts.runId)) {
      const err = new Error(`Run ${opts.runId} already exists`);
      err.code = "RUN_EXISTS";
      throw err;
    }
    fs.mkdirSync(opts.cwd, { recursive: true });
    const run = {
      runId: opts.runId,
      projectSlug: opts.projectSlug,
      cwd: opts.cwd,
      mode: opts.mode,
      model: opts.model,
      opts,
      status: "queued",
      createdAt: Date.now(),
      startedAt: null,
      endedAt: null,
      exitCode: null,
      sessionId: opts.sessionId || null,
      events: [],
      nextSeq: 1,
      subscribers: new Set(),
      proc: null,
      pid: null,
      aborted: false,
      stderrTail: "",
      finished: false,
    };
    this.runs.set(run.runId, run);
    this.queue.push(run);
    this.config.log("info", "run queued", { runId: run.runId, projectSlug: run.projectSlug, mode: run.mode, model: run.model });
    this._pump();
    return run;
  }

  _pump() {
    while (this.running < this.config.maxConcurrent && this.queue.length) {
      const run = this.queue.shift();
      if (run.status !== "queued") continue;
      this._start(run);
    }
  }

  _push(run, type, data) {
    if (type === "__internal_error") {
      this.config.log("warn", "normalizer error", { runId: run.runId, ...data });
      return;
    }
    if (type === "init" && data.sessionId) run.sessionId = data.sessionId;
    if (type === "result" && data.sessionId) run.sessionId = data.sessionId;
    const ev = { seq: run.nextSeq++, type, data };
    run.events.push(ev);
    const max = this.config.maxEventsPerRun;
    if (run.events.length > max * 1.1) run.events.splice(0, run.events.length - max);
    const frame = sseFrame(ev);
    for (const sub of run.subscribers) {
      try {
        sub.res.write(frame);
      } catch {
        /* ignore */
      }
    }
  }

  _start(run) {
    const c = this.config;
    const opts = run.opts;
    const features = c.features() || {};
    if (opts.agents) {
      const json = JSON.stringify(opts.agents);
      if (json.length > AGENTS_INLINE_MAX) {
        try {
          const f = path.join(require("os").tmpdir(), `nxeon-agents-${run.runId.replace(/[^A-Za-z0-9._-]/g, "_")}.json`);
          fs.writeFileSync(f, json, { mode: 0o644 });
          opts.agentsFile = f;
        } catch (err) {
          c.log("warn", "cannot write agents file", { runId: run.runId, error: err.message });
        }
      }
    }
    const args = buildRunArgs(opts, features, c);
    const env = buildChildEnv(c.env, opts);
    const norm = new Normalizer((type, data) => this._push(run, type, data));
    run.normalizer = norm;
    run.status = "running";
    run.startedAt = Date.now();
    this.running++;

    let proc;
    try {
      proc = spawn(c.claudeBin, args, { cwd: run.cwd, env, stdio: ["ignore", "pipe", "pipe"], detached: true });
    } catch (err) {
      this._finish(run, { exitCode: null, spawnError: err });
      return;
    }
    run.proc = proc;
    run.pid = proc.pid;
    c.log("info", "run started", { runId: run.runId, pid: proc.pid, args: args.slice(0, -1) });

    proc.stdout.setEncoding("utf8");
    proc.stdout.on("data", (d) => norm.write(d));
    proc.stderr.setEncoding("utf8");
    proc.stderr.on("data", (d) => {
      run.stderrTail = (run.stderrTail + d).slice(-8192);
    });

    let exitInfo = null;
    let closeTimer = null;
    proc.on("error", (err) => {
      c.log("error", "run spawn error", { runId: run.runId, error: err.message });
      this._finish(run, { exitCode: null, spawnError: err });
    });
    proc.on("exit", (code, signal) => {
      exitInfo = { code, signal };
      // stdout may be held open by background children; don't wait forever.
      closeTimer = setTimeout(() => this._finish(run, { exitCode: code, signal }), 2000);
    });
    proc.on("close", (code, signal) => {
      if (closeTimer) clearTimeout(closeTimer);
      const info = exitInfo || { code, signal };
      this._finish(run, { exitCode: info.code, signal: info.signal });
    });
  }

  _finish(run, { exitCode, signal, spawnError }) {
    if (run.finished) return;
    run.finished = true;
    if (run.killTimer) clearTimeout(run.killTimer);
    if (run.opts.agentsFile) fs.rm(run.opts.agentsFile, { force: true }, () => {});
    const norm = run.normalizer || new Normalizer((t, d) => this._push(run, t, d));
    norm.finish({ exitCode, aborted: run.aborted, stderr: run.stderrTail, spawnError });
    run.exitCode = exitCode ?? null;
    run.endedAt = Date.now();
    if (run.aborted) run.status = "aborted";
    else if (spawnError || norm.errorEmitted || (norm.lastResult && norm.lastResult.isError) || (!norm.sawResult && exitCode !== 0))
      run.status = "error";
    else run.status = "done";
    const done = { exitCode: run.exitCode };
    if (signal) done.signal = signal;
    if (run.aborted) done.aborted = true;
    this._push(run, "done", done);
    this.config.log("info", "run finished", { runId: run.runId, status: run.status, exitCode, signal, ms: run.endedAt - (run.startedAt || run.createdAt) });
    for (const sub of run.subscribers) this._endSub(run, sub);
    run.proc = null;
    if (run.startedAt) {
      this.running--;
      this._pump();
    }
  }

  _kill(run, sig) {
    if (!run.pid) return;
    try {
      process.kill(-run.pid, sig);
    } catch {
      try {
        process.kill(run.pid, sig);
      } catch {
        /* gone */
      }
    }
  }

  abort(runId) {
    const run = this.runs.get(runId);
    if (!run) return { found: false };
    if (TERMINAL.has(run.status)) return { found: true, status: run.status, alreadyFinished: true };
    run.aborted = true;
    if (run.status === "queued") {
      this.queue = this.queue.filter((r) => r !== run);
      this._finish(run, { exitCode: null });
      return { found: true, status: run.status };
    }
    this.config.log("info", "aborting run", { runId, pid: run.pid });
    this._kill(run, "SIGTERM");
    run.killTimer = setTimeout(() => this._kill(run, "SIGKILL"), this.config.killGraceMs);
    run.killTimer.unref?.();
    return { found: true, status: "aborting" };
  }

  /** Attach an SSE response. Replays events with seq >= fromSeq, then follows live. */
  subscribe(run, req, res, fromSeq = 1) {
    res.writeHead(200, {
      "Content-Type": "text/event-stream; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      Connection: "keep-alive",
      "X-Accel-Buffering": "no",
      "X-Run-Id": run.runId,
      "X-Run-Status": run.status,
    });
    res.write(`retry: 2000\n\n`);
    if (res.socket) res.socket.setNoDelay?.(true);
    for (const ev of run.events) if (ev.seq >= fromSeq) res.write(sseFrame(ev));
    if (run.finished) {
      res.end();
      return;
    }
    const sub = { res, hb: null };
    sub.hb = setInterval(() => {
      try {
        res.write(`: ping ${Date.now()}\n\n`);
      } catch {
        /* ignore */
      }
    }, this.config.heartbeatMs);
    sub.hb.unref?.();
    run.subscribers.add(sub);
    const detach = () => {
      clearInterval(sub.hb);
      run.subscribers.delete(sub);
    };
    // Client disconnect does NOT abort the run (the app may reattach via /v2/run/:id/events).
    req.on("close", detach);
    res.on("close", detach);
  }

  _endSub(run, sub) {
    clearInterval(sub.hb);
    run.subscribers.delete(sub);
    try {
      sub.res.end();
    } catch {
      /* ignore */
    }
  }

  info(run) {
    return {
      runId: run.runId,
      projectSlug: run.projectSlug,
      status: run.status,
      mode: run.mode,
      model: run.model,
      sessionId: run.sessionId,
      pid: run.pid,
      createdAt: run.createdAt,
      startedAt: run.startedAt,
      endedAt: run.endedAt,
      exitCode: run.exitCode,
      lastSeq: run.nextSeq - 1,
      firstSeq: run.events.length ? run.events[0].seq : null,
      subscribers: run.subscribers.size,
    };
  }

  list({ all = false } = {}) {
    const out = [];
    for (const run of this.runs.values()) if (all || !TERMINAL.has(run.status)) out.push(this.info(run));
    return out;
  }

  stats() {
    return { running: this.running, queued: this.queue.length, retained: this.runs.size };
  }

  gc(now = Date.now()) {
    for (const [id, run] of this.runs) {
      if (run.finished && run.endedAt && now - run.endedAt > this.config.retentionMs && run.subscribers.size === 0) {
        this.runs.delete(id);
      }
    }
  }
}

function sseFrame(ev) {
  return `id: ${ev.seq}\nevent: ${ev.type}\ndata: ${JSON.stringify(ev.data)}\n\n`;
}

