const cliInfo = { version: null, features: {}, detected: false };

function execText(bin, args, timeoutMs = 20000) {
  return new Promise((resolve) => {
    execFile(bin, args, { timeout: timeoutMs, maxBuffer: 4 * 1024 * 1024, env: { ...process.env, CLAUDEBOX_API_KEY: "" } }, (err, stdout, stderr) => {
      resolve({ ok: !err, out: String(stdout || "") + String(stderr || "") });
    });
  });
}

function parseHelpFeatures(help) {
  const features = {};
  const m = /--permission-mode <mode>[\s\S]*?\(choices:\s*([^)]*)\)/.exec(help);
  if (m) features.permissionModes = [...m[1].matchAll(/"([^"]+)"/g)].map((x) => x[1]);
  features.permissionPrompts = /--permission-prompts\b/.test(help);
  features.includePartialMessages = /--include-partial-messages\b/.test(help);
  features.effort = /--effort\b/.test(help);
  features.autocompact = /--autocompact\b/.test(help);
  features.agents = /--agents\b/.test(help);
  features.forwardSubagentText = /--forward-subagent-text\b/.test(help);
  return features;
}

async function detectCli() {
  const [ver, help] = await Promise.all([execText(CLAUDE_BIN, ["--version"]), execText(CLAUDE_BIN, ["--help"])]);
  if (ver.ok) cliInfo.version = (ver.out.trim().split(/\s+/)[0] || "").trim() || null;
  if (help.ok || help.out) cliInfo.features = parseHelpFeatures(help.out);
  cliInfo.detected = true;
  log("info", "claude CLI detected", { version: cliInfo.version, features: cliInfo.features });
}

function authMode() {
  if (process.env.CLAUDE_CODE_OAUTH_TOKEN) return "oauth";
  if (process.env.ANTHROPIC_API_KEY) return "api_key";
  const cfgDir = process.env.CLAUDE_CONFIG_DIR || path.join(process.env.HOME || "/home/claude", ".claude");
  try {
    if (fs.statSync(path.join(cfgDir, ".credentials.json")).isFile()) return "credentials";
  } catch {
    /* none */
  }
  return "none";
}

function checkBearer(req) {
  if (!CLAUDEBOX_API_KEY) return ALLOW_NO_AUTH;
  const auth = String(req.headers.authorization || "");
  const expected = `Bearer ${CLAUDEBOX_API_KEY}`;
  const a = Buffer.from(auth);
  const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

async function readJSONBody(req, res, limit = 4 * 1024 * 1024) {
  let size = 0;
  const chunks = [];
  for await (const c of req) {
    size += c.length;
    if (size > limit) {
      sendJSON(res, 413, { error: "Body too large" });
      return undefined;
    }
    chunks.push(c);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw.trim()) return {};
  try {
    return JSON.parse(raw);
  } catch {
    sendJSON(res, 400, { error: "Invalid JSON body" });
    return undefined;
  }
}

const runs = new RunManager({
  claudeBin: CLAUDE_BIN,
  projectsDir: PROJECTS_DIR,
  uploadsDir: UPLOADS_DIR,
  maxConcurrent: MAX_CONCURRENT,
  retentionMs: RUN_RETENTION_MS,
  previewPortMin: PREVIEW_PORT_MIN,
  previewPortMax: PREVIEW_PORT_MAX,
  autoPermissionMode: AUTO_PERMISSION_MODE,
  thinkingDisplay: process.env.THINKING_DISPLAY ?? "summarized",
  forwardSubagentText: process.env.FORWARD_SUBAGENT_TEXT !== "0",
  features: () => cliInfo.features,
  log,
});

const previews = new PreviewManager({
  projectsDir: PROJECTS_DIR,
  portMin: PREVIEW_PORT_MIN,
  portMax: PREVIEW_PORT_MAX,
  allowedHost: process.env.PREVIEW_ALLOWED_HOST || "claudebox",
  protectedPgids: () => runs.list().map((r) => r.pid).filter(Boolean),
  log,
});

const git = new GitManager({ projectsDir: PROJECTS_DIR, log });

async function handleV2(req, res, url) {
  const p = url.pathname;
  const m = req.method;

  if (!checkBearer(req)) {
    const msg = CLAUDEBOX_API_KEY ? "Invalid or missing bearer token" : "CLAUDEBOX_API_KEY is not configured";
    sendJSON(res, 401, { error: msg });
    return;
  }

  if (m === "POST" && p === "/v2/run") {
    const body = await readJSONBody(req, res);
    if (body === undefined) return;
    const { opts, error } = runs.validate(body);
    if (error) return sendJSON(res, 400, { error });
    let run;
    try {
      run = runs.create(opts);
    } catch (err) {
      if (err.code === "RUN_EXISTS") {
        return sendJSON(res, 409, { error: err.message, hint: `GET /v2/run/${opts.runId}/events?fromSeq=1 to reattach` });
      }
      return sendJSON(res, 500, { error: err.message });
    }
    runs.subscribe(run, req, res, 1);
    return;
  }

  let mm;
  if (m === "GET" && (mm = /^\/v2\/run\/([^/]+)\/events$/.exec(p))) {
    const run = runs.get(decodeURIComponent(mm[1]));
    if (!run) return sendJSON(res, 404, { error: "Unknown runId (never existed or expired)" });
    let fromSeq = parseInt(url.searchParams.get("fromSeq") || "", 10);
    const lastEventId = parseInt(String(req.headers["last-event-id"] || ""), 10);
    if (!Number.isFinite(fromSeq)) fromSeq = Number.isFinite(lastEventId) ? lastEventId + 1 : 1;
    runs.subscribe(run, req, res, fromSeq);
    return;
  }

  if (m === "GET" && (mm = /^\/v2\/runs?\/([^/]+)$/.exec(p)) && mm[1] !== "runs") {
    const run = runs.get(decodeURIComponent(mm[1]));
    if (!run) return sendJSON(res, 404, { error: "Unknown runId" });
    return sendJSON(res, 200, runs.info(run));
  }

  if (m === "POST" && p === "/v2/abort") {
    const body = await readJSONBody(req, res);
    if (body === undefined) return;
    if (typeof body.runId !== "string") return sendJSON(res, 400, { error: "Missing runId" });
    const r = runs.abort(body.runId);
    if (!r.found) return sendJSON(res, 404, { error: "Unknown runId" });
    return sendJSON(res, 200, { ok: true, runId: body.runId, ...r });
  }

  if (m === "GET" && p === "/v2/runs") {
    const all = url.searchParams.get("all") === "1";
    return sendJSON(res, 200, { runs: runs.list({ all }), ...runs.stats(), maxConcurrent: MAX_CONCURRENT });
  }

  if (p.startsWith("/v2/git/")) {
    if (m !== "POST") return sendJSON(res, 405, { error: "Use POST" });
    const body = await readJSONBody(req, res);
    if (body === undefined) return;
    try {
      return sendJSON(res, 200, await handleGit(git, p.slice("/v2/git/".length), body));
    } catch (err) {
      if (err instanceof GitError) return sendJSON(res, err.status, { error: err.message, ...err.extra });
      throw err;
    }
  }

  if (p.startsWith("/v2/preview")) {
    if (m === "GET" && p === "/v2/previews") return sendJSON(res, 200, { previews: await previews.list() });
    if (m === "GET" && p === "/v2/preview/status") {
      const slug = url.searchParams.get("projectSlug") || "";
      if (!SLUG_RE.test(slug)) return sendJSON(res, 400, { error: "Invalid projectSlug" });
      const worktree = url.searchParams.get("worktree") || null;
      if (worktree && !WORKTREE_RE.test(worktree)) return sendJSON(res, 400, { error: "Invalid worktree" });
      const port = url.searchParams.get("port") ? parseInt(url.searchParams.get("port"), 10) : undefined;
      if (port !== undefined && !(port >= PREVIEW_PORT_MIN && port <= PREVIEW_PORT_MAX)) return sendJSON(res, 400, { error: "Invalid port" });
      return sendJSON(res, 200, await previews.status(previews.target(slug, worktree).key, port));
    }
    if (m === "POST" && (p === "/v2/preview/start" || p === "/v2/preview/stop")) {
      const body = await readJSONBody(req, res);
      if (body === undefined) return;
      if (typeof body.projectSlug !== "string" || !SLUG_RE.test(body.projectSlug)) return sendJSON(res, 400, { error: "Invalid projectSlug" });
      const worktree = body.worktree == null || body.worktree === "" ? null : body.worktree;
      if (worktree !== null && (typeof worktree !== "string" || !WORKTREE_RE.test(worktree))) return sendJSON(res, 400, { error: "Invalid worktree" });
      const port = body.port == null ? undefined : Number(body.port);
      if (port !== undefined && !(Number.isInteger(port) && port >= PREVIEW_PORT_MIN && port <= PREVIEW_PORT_MAX))
        return sendJSON(res, 400, { error: `port must be an integer in ${PREVIEW_PORT_MIN}-${PREVIEW_PORT_MAX}` });
      if (p === "/v2/preview/start") {
        if (port === undefined) return sendJSON(res, 400, { error: "Missing port" });
        const r = await previews.start({ projectSlug: body.projectSlug, worktree, port, command: body.command });
        return sendJSON(res, r.status, r.body);
      }
      return sendJSON(res, 200, await previews.stop({ projectSlug: body.projectSlug, worktree, port }));
    }
  }

  sendJSON(res, 404, { error: "Not found" });
}

// ---------------------------------------------------------------------------
// Server
// ---------------------------------------------------------------------------

const server = http.createServer(async (req, res) => {
  let url;
  try {
    url = new URL(req.url, "http://localhost");
  } catch {
    sendJSON(res, 400, { error: "Bad URL" });
    return;
  }

  try {
    // --- Health check ---
    if (req.method === "GET" && url.pathname === "/health") {
      const st = runs.stats();
      sendJSON(res, 200, {
        status: "ok",
        activeRequests,
        version: PKG_VERSION,
        claudeVersion: cliInfo.version,
        authMode: authMode(),
        activeRuns: st.running,
        queuedRuns: st.queued,
        maxConcurrent: MAX_CONCURRENT,
        firewallMode: process.env.FIREWALL_MODE || null,
        autoPermissionMode: AUTO_PERMISSION_MODE,
      });
      return;
    }

    if (url.pathname.startsWith("/v2/")) {
      await handleV2(req, res, url);
      return;
    }
  } catch (err) {
    log("error", "request failed", { path: url.pathname, error: err.message });
    if (!res.headersSent) sendJSON(res, 500, { error: err.message });
    else res.end();
    return;
  }

  // --- Custom prompt API ---
  if (req.method === "POST" && req.url === "/prompt") {
    if (activeRequests >= MAX_CONCURRENT) {
      log("warn", "rejected request, at capacity", { activeRequests });
      sendJSON(res, 429, { error: "Too many concurrent requests" });
      return;
    }

    activeRequests++;
    try {
      const raw = await readBody(req);
      let body;
      try {
        body = JSON.parse(raw);
      } catch {
        sendJSON(res, 400, { error: "Invalid JSON body" });
        return;
      }

      if (!body.prompt) {
        sendJSON(res, 400, { error: "Missing 'prompt' field" });
        return;
      }

      const result = await runClaude(body.prompt, body.options || {});
      res.writeHead(200, { "Content-Type": "application/json" });
      res.end(result);
    } catch (err) {
      sendJSON(res, 500, { error: err.message });
    } finally {
      activeRequests--;
    }
    return;
  }

  // --- OpenAI-compatible endpoints ---
  if (OPENAI_COMPAT) {
    if (req.method === "POST" && req.url === "/v1/chat/completions") {
      await handleChatCompletions(req, res);
      return;
    }

    if (req.method === "GET" && req.url === "/v1/models") {
      handleModels(req, res);
      return;
    }
  }

  // --- 404 ---
  const routes = [
    "POST /prompt",
    "GET /health",
    "POST /v2/run",
    "GET /v2/run/:runId/events",
    "POST /v2/abort",
    "GET /v2/runs",
    "POST /v2/preview/start",
    "POST /v2/preview/stop",
    "GET /v2/preview/status",
    "POST /v2/git/<op>",
  ];
  if (OPENAI_COMPAT) {
    routes.push("POST /v1/chat/completions", "GET /v1/models");
  }
  sendJSON(res, 404, { error: `Not found. Available: ${routes.join(", ")}` });
});

server.keepAliveTimeout = 65000;
server.requestTimeout = 0; // SSE streams are long-lived

async function start(port = PORT, host = "0.0.0.0") {
  await Promise.race([detectCli(), new Promise((r) => setTimeout(r, 20000))]);
  if (!CLAUDEBOX_API_KEY && !ALLOW_NO_AUTH) {
    log("warn", "CLAUDEBOX_API_KEY not set: /v2/* endpoints will reject all requests (set CLAUDEBOX_ALLOW_NO_AUTH=1 to disable auth)");
  }
  await new Promise((resolve) => server.listen(port, host, resolve));
  log("info", `claudebox server listening on port ${server.address().port}`, {
    version: PKG_VERSION,
    claudeVersion: cliInfo.version,
    authMode: authMode(),
    maxConcurrent: MAX_CONCURRENT,
    openaiCompat: OPENAI_COMPAT,
    projectsDir: PROJECTS_DIR,
  });
  return server;
}

function shutdown(sig) {
  log("info", "shutting down", { signal: sig });
  runs.close();
  previews.stopAll().finally(() => process.exit(0));
  setTimeout(() => process.exit(0), 5000).unref();
}

if (require.main === module) {
  process.on("SIGTERM", () => shutdown("SIGTERM"));
  process.on("SIGINT", () => shutdown("SIGINT"));
  start().catch((err) => {
    log("error", "failed to start", { error: err.message });
    process.exit(1);
  });
}

module.exports = { buildClaudeArgs, server, start, runs, previews, git, parseHelpFeatures, cliInfo };

import type { FastifyPluginAsync, FastifyRequest } from 'fastify';
import { z } from 'zod';
import { requireProject, requireUser, type ProjectRow, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { now } from '../db.js';
import { badRequest, conflict, notFound } from '../lib/errors.js';
import {
  activeBranches, activeRunCount, allocatePort, branchDTO, branchParam, ensureGit, getBranch, gitError, newBranchId,
  previewPath, validBranchName, worktreeDirName, worktreePath, type BranchRow,
} from '../lib/branches.js';
import type { RunRow } from '../dto.js';
import fs from 'node:fs';

const createBody = z.object({ name: z.string().trim().min(1).max(100), base: z.string().trim().max(100).nullable().optional() });
const renameBody = z.object({ name: z.string().trim().min(1).max(100) });
const mergeBody = z.object({ close: z.boolean().optional().default(true) });
const checkpointBody = z.object({ message: z.string().max(200).optional() });
const SHA_RE = /^[0-9a-f]{7,40}$/;

interface GitStatus { worktree: string; ahead?: number; behind?: number; filesChanged?: number; dirty?: boolean; missing?: boolean; error?: string }
interface Commit { sha: string; parents: string[]; time: number; author: string; message: string; filesChanged: number; insertions: number; deletions: number }

export function resolvePrompt(main: string, conflicts: string[]): string {
  return `Merging this branch into "${main}" hit conflicts in: ${conflicts.join(', ')}. ` +
    `Please merge the latest "${main}" into this branch (run \`git merge ${main}\`), resolve every conflicted file so both sides' intent is kept, ` +
    `then \`git add\` them and \`git commit --no-edit\` to conclude the merge (this is an explicit request to use git). Keep the summary short.`;
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cb } = ctx;

    const load = (req: FastifyRequest, min: 'viewer' | 'editor') => {
      const u = requireUser(req);
      return { u, ...requireProject(db, u, (req.params as { id: string }).id, min) };
    };
    const loadBranch = (project: ProjectRow, name: string) => {
      const b = getBranch(db, project.id, name);
      if (!b) throw notFound(`Branch "${name}" not found`);
      return b;
    };
    const changed = (p: ProjectRow, what: 'branches' | 'history' | 'topics', branch: string | null = null) =>
      ctx.hub.broadcastProject(p.id, { t: 'project_changed', projectId: p.id, what, branch });
    const assertIdle = (p: ProjectRow, branch: string | null, what: string) => {
      if (activeRunCount(db, p.id, branch)) throw conflict(`Claude is still working on ${branch ? `branch "${branch}"` : 'main'} — wait for the run to finish before ${what}.`, 'run_in_progress');
    };
    const git = async <T>(op: string, body: Record<string, unknown>) => {
      try {
        return await cb.git<T>(op, body);
      } catch (err) {
        throw gitError(err);
      }
    };
    /** A branch's base, falling back to main when the base branch was closed. */
    const baseOf = (p: ProjectRow, b: BranchRow, main: string) => (b.base === main || getBranch(db, p.id, b.base) ? b.base : main);

    /** Close a branch: stop its preview + watcher, drop the worktree, move its conversations to main. */
    async function closeBranch(p: ProjectRow, b: BranchRow, status: 'merged' | 'discarded', mergedSha: string | null) {
      try {
        await cb.previewStop(p.slug, b.preview_port, b.dir);
      } catch {
        /* claudebox down / not running */
      }
      ctx.watchers.stop(p.id, b.name);
      await git('branch/remove', { projectSlug: p.slug, branch: b.name, worktree: b.dir, deleteRef: true });
      db.transaction(() => {
        db.prepare(`UPDATE branches SET status = ?, closed_at = ?, merged_sha = ? WHERE id = ?`).run(status, now(), mergedSha, b.id);
        // their Claude sessions lived in the worktree (cwd) — they continue as fresh sessions on main
        db.prepare(`UPDATE conversations SET branch = NULL, claude_session_id = NULL, context_tokens = NULL WHERE project_id = ? AND branch = ?`).run(p.id, b.name);
      })();
    }

    async function liveStatus(p: ProjectRow, branches: BranchRow[], main: string) {
      const live = new Map<string, GitStatus>();
      let mainDirty: boolean | null = null;
      if (!branches.length) {
        return { live, mainDirty };
      }
      try {
        const r = await cb.git<{ mainDirty: boolean; branches: GitStatus[] }>('status', {
          projectSlug: p.slug, branches: branches.map((b) => ({ worktree: b.dir, base: baseOf(p, b, main) })),
        }, 20_000);
        mainDirty = r.mainDirty;
        const upd = db.prepare(`UPDATE branches SET ahead = ?, behind = ?, files_changed = ?, stat_at = ? WHERE id = ?`);
        for (const s of r.branches ?? []) {
          live.set(s.worktree, s);
          const b = branches.find((x) => x.dir === s.worktree);
          if (b && s.filesChanged != null) upd.run(s.ahead ?? 0, s.behind ?? 0, s.filesChanged, now(), b.id);
        }
      } catch (err) {
        ctx.log.warn({ err: (err as Error).message, project: p.slug }, 'branch status failed');
      }
      return { live, mainDirty };
    }

    // ---------------- branches ----------------

    app.get('/api/projects/:id/branches', async (req) => {
      const { project } = load(req, 'viewer');
      const main = await ensureGit(ctx, project);
      const all = (req.query as { all?: string }).all === '1';
      const rows = all
        ? (db.prepare(`SELECT * FROM branches WHERE project_id = ? ORDER BY status = 'active' DESC, created_at`).all(project.id) as BranchRow[])
        : activeBranches(db, project.id);
      const active = rows.filter((b) => b.status === 'active');
      const { live } = await liveStatus(project, active, main);
      const running = new Set((db.prepare(`SELECT DISTINCT branch FROM runs WHERE project_id = ? AND status IN ('queued','running')`).all(project.id) as { branch: string | null }[]).map((r) => r.branch ?? ''));
      return {
        main: { name: main, previewPort: project.preview_port, previewPath: previewPath(project.slug), running: running.has('') },
        branches: rows.map((b) => ({ ...branchDTO(b, project, b.status === 'active' ? live.get(b.dir) : null), running: b.status === 'active' && running.has(b.name) })),
      };
    });

    app.post('/api/projects/:id/branches', async (req, reply) => {
      const { u, project } = load(req, 'editor');
      if (project.archived) throw conflict('Project is archived', 'archived');
      const body = createBody.parse(req.body ?? {});
      const main = await ensureGit(ctx, project);
      const err = validBranchName(body.name, project);
      if (err) throw badRequest(err, 'invalid_branch');
      if (getBranch(db, project.id, body.name)) throw conflict(`Branch "${body.name}" already exists`, 'branch_exists');
      const base = !body.base || body.base === 'main' ? main : body.base;
      if (base !== main && !getBranch(db, project.id, base)) throw notFound(`Base branch "${base}" not found`);
      const id = newBranchId();
      let row: BranchRow | undefined;
      db.transaction(() => {
        let dir = worktreeDirName(body.name);
        const taken = (d: string) => !!db.prepare(`SELECT 1 FROM branches WHERE project_id = ? AND dir = ?`).get(project.id, d) || fs.existsSync(worktreePath(ctx.cfg, project.slug, d));
        for (let i = 2; taken(dir); i++) dir = `${worktreeDirName(body.name).slice(0, 58)}-${i}`;
        const port = allocatePort(ctx);
        db.prepare(`INSERT INTO branches(id, project_id, name, dir, base, preview_port, status, created_by, created_at, files_changed, ahead, behind, stat_at)
          VALUES (?,?,?,?,?,?, 'active', ?,?, 0, 0, 0, ?)`).run(id, project.id, body.name, dir, base, port, u.id, now(), now());
        row = db.prepare(`SELECT * FROM branches WHERE id = ?`).get(id) as BranchRow;
      })();
      try {
        await git('branch/create', { projectSlug: project.slug, branch: row!.name, worktree: row!.dir, base });
      } catch (e) {
        db.prepare(`DELETE FROM branches WHERE id = ?`).run(id);
        throw e;
      }
      ctx.audit(req, 'branch_create', project.id, { branch: row!.name, base });
      changed(project, 'branches');
      reply.code(201);
      return branchDTO(row!, project, { ahead: 0, behind: 0, filesChanged: 0, dirty: false });
    });

    app.patch('/api/projects/:id/branches/:name', async (req) => {
      const { project } = load(req, 'editor');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const body = renameBody.parse(req.body ?? {});
      if (body.name === b.name) return branchDTO(b, project);
      await ensureGit(ctx, project);
      const err = validBranchName(body.name, project);
      if (err) throw badRequest(err, 'invalid_branch');
      if (getBranch(db, project.id, body.name)) throw conflict(`Branch "${body.name}" already exists`, 'branch_exists');
      assertIdle(project, b.name, 'renaming it');
      await git('branch/rename', { projectSlug: project.slug, from: b.name, to: body.name });
      db.transaction(() => {
        db.prepare(`UPDATE branches SET name = ? WHERE id = ?`).run(body.name, b.id);
        db.prepare(`UPDATE branches SET base = ? WHERE project_id = ? AND base = ? AND status = 'active'`).run(body.name, project.id, b.name);
        db.prepare(`UPDATE conversations SET branch = ? WHERE project_id = ? AND branch = ?`).run(body.name, project.id, b.name);
        db.prepare(`UPDATE runs SET branch = ? WHERE project_id = ? AND branch = ?`).run(body.name, project.id, b.name);
      })();
      ctx.watchers.stop(project.id, b.name);
      ctx.audit(req, 'branch_rename', project.id, { from: b.name, to: body.name });
      changed(project, 'branches');
      return branchDTO(db.prepare(`SELECT * FROM branches WHERE id = ?`).get(b.id) as BranchRow, project);
    });

    /** Discard: remove the worktree and delete the git branch. */
    app.delete('/api/projects/:id/branches/:name', async (req) => {
      const { project } = load(req, 'editor');
      const b = loadBranch(project, (req.params as { name: string }).name);
      assertIdle(project, b.name, 'discarding it');
      if (db.prepare(`SELECT 1 FROM branches WHERE project_id = ? AND base = ? AND status = 'active'`).get(project.id, b.name))
        throw conflict('Other branches were created from this one; discard or merge them first.', 'has_dependents');
      await ensureGit(ctx, project);
      await closeBranch(project, b, 'discarded', null);
      ctx.audit(req, 'branch_discard', project.id, { branch: b.name });
      changed(project, 'branches');
      return { ok: true };
    });

    app.get('/api/projects/:id/branches/:name/diff', async (req) => {
      const { project } = load(req, 'viewer');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const main = await ensureGit(ctx, project);
      const base = baseOf(project, b, main);
      const r = await git<{ files: { path: string }[]; additions: number; deletions: number; mergeBase: string; head: string }>('diff', {
        projectSlug: project.slug, worktree: b.dir, base,
      });
      db.prepare(`UPDATE branches SET files_changed = ?, stat_at = ? WHERE id = ?`).run(r.files.length, now(), b.id);
      return { branch: b.name, ...r, base };
    });

    app.get('/api/projects/:id/branches/:name/diff/file', async (req) => {
      const { project } = load(req, 'viewer');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const p = (req.query as { path?: string }).path;
      if (!p) throw badRequest('Missing path');
      const main = await ensureGit(ctx, project);
      return git('file-diff', { projectSlug: project.slug, worktree: b.dir, base: baseOf(project, b, main), path: p });
    });

    app.post('/api/projects/:id/branches/:name/merge', async (req) => {
      const { project } = load(req, 'editor');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const body = mergeBody.parse(req.body ?? {});
      const main = await ensureGit(ctx, project);
      assertIdle(project, b.name, 'merging');
      assertIdle(project, null, 'merging into it');
      const r = await git<{ ok: boolean; sha?: string; conflicts?: string[]; upToDate?: boolean }>('merge', {
        projectSlug: project.slug, branch: b.name, worktree: b.dir, into: main,
      });
      if (!r.ok) {
        ctx.audit(req, 'branch_merge_conflict', project.id, { branch: b.name, conflicts: r.conflicts });
        return { ok: false, conflicts: r.conflicts ?? [], resolvePrompt: resolvePrompt(main, r.conflicts ?? []) };
      }
      const hasDependents = !!db.prepare(`SELECT 1 FROM branches WHERE project_id = ? AND base = ? AND status = 'active'`).get(project.id, b.name);
      const close = body.close && !hasDependents;
      if (close) await closeBranch(project, b, 'merged', r.sha ?? null);
      ctx.audit(req, 'branch_merge', project.id, { branch: b.name, into: main, sha: r.sha, closed: close });
      changed(project, 'branches');
      changed(project, 'history', null);
      void ctx.runs.autoStartPreview(project.id, null);
      return { ok: true, sha: r.sha ?? null, upToDate: !!r.upToDate, closed: close, into: main };
    });

    // ---------------- history / checkpoints / undo ----------------

    app.get('/api/projects/:id/history', async (req) => {
      const { project } = load(req, 'viewer');
      const q = req.query as { branch?: string; limit?: string };
      const b = branchParam(db, project, q.branch);
      const main = await ensureGit(ctx, project);
      const r = await git<{ commits: Commit[]; dirty: boolean; branch: string | null }>('history', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), limit: Math.min(200, Number(q.limit) || 60),
      });
      const shas = r.commits.map((c) => c.sha);
      const runs = new Map<string, Pick<RunRow, 'id' | 'conversation_id' | 'undo_sha' | 'user_id'> & { title: string | null }>();
      if (shas.length) {
        for (const x of db
          .prepare(
            `SELECT r.id, r.conversation_id, r.undo_sha, r.user_id, r.commit_sha, c.title FROM runs r LEFT JOIN conversations c ON c.id = r.conversation_id
             WHERE r.project_id = ? AND r.commit_sha IN (${shas.map(() => '?').join(',')})`,
          )
          .all(project.id, ...shas) as (Pick<RunRow, 'id' | 'conversation_id' | 'undo_sha' | 'user_id'> & { commit_sha: string; title: string | null })[])
          runs.set(x.commit_sha, x);
      }
      return {
        branch: b?.name ?? null,
        checkout: r.branch ?? (b ? b.name : main),
        main,
        dirty: r.dirty,
        commits: r.commits.map((c) => {
          const run = runs.get(c.sha);
          return {
            sha: c.sha, short: c.sha.slice(0, 7), message: c.message, time: new Date(c.time).toISOString(), author: c.author,
            filesChanged: c.filesChanged, insertions: c.insertions, deletions: c.deletions,
            isMerge: c.parents.length > 1, isRoot: c.parents.length === 0,
            run: run ? { id: run.id, conversationId: run.conversation_id, conversationTitle: run.title, undone: !!run.undo_sha } : null,
          };
        }),
      };
    });

    app.post('/api/projects/:id/checkpoint', async (req) => {
      const { project } = load(req, 'editor');
      const b = branchParam(db, project, (req.query as { branch?: string }).branch);
      const body = checkpointBody.parse(req.body ?? {});
      const main = await ensureGit(ctx, project);
      const msg = `nxeon: ${(body.message || 'manual checkpoint').replace(/\s+/g, ' ').trim().slice(0, 60)}`;
      const r = await git<{ sha: string | null; files?: number; skipped?: string }>('checkpoint', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), message: msg, expectBranch: b ? b.name : main,
      });
      if (r.skipped) throw conflict(`Checkpoint skipped: ${r.skipped === 'head_moved' ? 'the checkout is on another git branch' : r.skipped}`, 'checkpoint_skipped');
      if (r.sha) changed(project, 'history', b?.name ?? null);
      ctx.audit(req, 'checkpoint', project.id, { branch: b?.name ?? null, sha: r.sha });
      return { sha: r.sha, files: r.files ?? 0 };
    });

    async function revert(req: FastifyRequest, u: UserRow, project: ProjectRow, b: BranchRow | null, sha: string) {
      if (!SHA_RE.test(sha)) throw badRequest('Invalid commit');
      const main = await ensureGit(ctx, project);
      assertIdle(project, b?.name ?? null, 'undoing');
      const r = await git<{ ok: boolean; sha?: string | null; conflicts?: string[]; empty?: boolean }>('revert', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), sha, expectBranch: b ? b.name : main,
      });
      if (!r.ok) return { ok: false, conflicts: r.conflicts ?? [] };
      db.prepare(`UPDATE runs SET undo_sha = ? WHERE project_id = ? AND commit_sha LIKE ? || '%'`).run(r.sha ?? 'empty', project.id, sha);
      ctx.audit(req, 'undo', project.id, { branch: b?.name ?? null, sha, revert: r.sha, by: u.id });
      changed(project, 'history', b?.name ?? null);
      return { ok: true, sha: r.sha ?? null, empty: !!r.empty };
    }

    app.post('/api/projects/:id/history/:sha/revert', async (req) => {
      const { u, project } = load(req, 'editor');
      const b = branchParam(db, project, (req.query as { branch?: string }).branch);
      return revert(req, u, project, b, (req.params as { sha: string }).sha);
    });

    /** "Undo this run": revert the run's auto-checkpoint commit (creates a new commit). */
    app.post('/api/runs/:id/undo', async (req) => {
      const u = requireUser(req);
      const run = db.prepare(`SELECT * FROM runs WHERE id = ?`).get((req.params as { id: string }).id) as RunRow | undefined;
      if (!run) throw notFound('Run not found');
      const { project } = requireProject(db, u, run.project_id, 'editor');
      if (!run.commit_sha) throw conflict('This run has no checkpoint (it changed no files)', 'no_checkpoint');
      if (run.undo_sha) throw conflict('This run was already undone', 'already_undone');
      const b = run.branch ? getBranch(db, project.id, run.branch) : null;
      if (run.branch && !b) throw conflict(`Branch "${run.branch}" is closed`, 'branch_closed');
      return revert(req, u, project, b, run.commit_sha);
    });
  };
import { request } from 'undici';
import type { Config } from './config.js';

export interface V2RunBody {
  runId: string;
  prompt: string;
  projectSlug: string;
  sessionId: string | null;
  model: string;
  mode: string;
  thinking: string;
  attachments: string[];
  appendSystemPrompt: string;
  maxTurns: number;
  previewPort: number;
  /** Branch runs: worktree dir under .branches/<slug>/ (cwd + preview key <slug>--<worktree>). */
  worktree?: string;
  authToken?: string;
  /** Context size at which to auto-compact (0/absent = CLI default). */
  autocompactTokens?: number;
  /** Custom subagents → `--agents`. */
  agents?: Record<string, { description: string; prompt: string; tools?: string[]; model?: string }>;
  /** Lead agent → `--agent` (must be a key of `agents`). */
  agent?: string;
}

export interface PreviewStatusUpstream {
  projectSlug?: string;
  running: boolean;
  managed?: boolean;
  listening?: boolean;
  port: number | null;
  pid?: number | null;
  kind?: string | null;
  command?: string | null;
  startedAt?: number | null;
  exitCode?: number | null;
  logTail?: string[] | string;
}

export class ClaudeboxError extends Error {
  constructor(public statusCode: number, message: string, public body: unknown = null) {
    super(message);
  }
}

export class Claudebox {
  constructor(private cfg: Config) {}

  private headers(extra: Record<string, string> = {}) {
    return {
      authorization: `Bearer ${this.cfg.claudeboxApiKey}`,
      ...extra,
    };
  }

  /** Start a run; returns the raw undici response (SSE body). */
  startRun(body: V2RunBody, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run`, {
      method: 'POST',
      headers: this.headers({ 'content-type': 'application/json', accept: 'text/event-stream' }),
      body: JSON.stringify(body),
      signal,
      headersTimeout: 60_000,
      bodyTimeout: 0,
    });
  }

  /** Re-attach to a run's buffered event stream. */
  attach(runId: string, fromSeq: number, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run/${encodeURIComponent(runId)}/events?fromSeq=${fromSeq}`, {
      method: 'GET',
      headers: this.headers({ accept: 'text/event-stream' }),
      signal,
      headersTimeout: 30_000,
      bodyTimeout: 0,
    });
  }

  private async json<T>(method: 'GET' | 'POST', path: string, body?: unknown, timeoutMs = 15_000): Promise<T> {
    const res = await request(`${this.cfg.claudeboxUrl}${path}`, {
      method,
      headers: this.headers(body !== undefined ? { 'content-type': 'application/json' } : {}),
      body: body !== undefined ? JSON.stringify(body) : undefined,
      headersTimeout: timeoutMs,
      bodyTimeout: timeoutMs,
    });
    const text = await res.body.text();
    let data: unknown = text;
    try {
      data = JSON.parse(text);
    } catch {
      /* not json */
    }
    if (res.statusCode >= 400) {
      const msg =
        (data as { error?: string | { message?: string } })?.error ?? (typeof data === 'string' ? data : `HTTP ${res.statusCode}`);
      throw new ClaudeboxError(res.statusCode, typeof msg === 'string' ? msg : msg?.message ?? `HTTP ${res.statusCode}`, data);
    }
    return data as T;
  }

  abort(runId: string) {
    return this.json<unknown>('POST', '/v2/abort', { runId });
  }
  previewStart(projectSlug: string, port: number, command?: string | null, worktree?: string | null) {
    return this.json<PreviewStatusUpstream>(
      'POST', '/v2/preview/start', { projectSlug, port, ...(command ? { command } : {}), ...(worktree ? { worktree } : {}) }, 60_000,
    );
  }
  previewStop(projectSlug: string, port?: number, worktree?: string | null) {
    return this.json<PreviewStatusUpstream & { stopped?: boolean }>('POST', '/v2/preview/stop', {
      projectSlug, ...(port ? { port } : {}), ...(worktree ? { worktree } : {}),
    });
  }
  previewStatus(projectSlug: string, port?: number, worktree?: string | null) {
    return this.json<PreviewStatusUpstream>(
      'GET',
      `/v2/preview/status?projectSlug=${encodeURIComponent(projectSlug)}${port ? `&port=${port}` : ''}${worktree ? `&worktree=${encodeURIComponent(worktree)}` : ''}`,
    );
  }
  previews(timeoutMs = 2000) {
    return this.json<{ previews: PreviewStatusUpstream[] }>('GET', '/v2/previews', undefined, timeoutMs);
  }
  /** POST /v2/git/<op> (see claudebox/lib/git.js). */
  git<T = Record<string, unknown>>(op: string, body: Record<string, unknown>, timeoutMs = 130_000) {
    return this.json<T>('POST', `/v2/git/${op}`, body, timeoutMs);
  }
  health() {
    return this.json<Record<string, unknown>>('GET', '/health', undefined, 5000);
  }
}

import type { FastifyPluginAsync } from 'fastify';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { pipeline } from 'node:stream/promises';
import sharp from 'sharp';
import { request, FormData } from 'undici';
import { projectRole, requireProject, requireUser, type UserRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { now } from '../db.js';
import { attachmentDTO, type UploadRow } from '../dto.js';
import { badRequest, forbidden, HttpError, notFound } from '../lib/errors.js';
import { contentDisposition, mimeFromName, sanitizeFilename } from '../lib/safepath.js';

const THUMB = '.thumb.webp';
const THUMBABLE = new Set(['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/avif', 'image/tiff', 'image/bmp']);
const ACTIVE_TYPES = /^(text\/html|application\/xhtml|image\/svg|application\/xml|text\/xml|text\/javascript|application\/javascript)/i;
const INLINE_TYPES = /^(image\/|audio\/|video\/|application\/pdf|text\/plain)/i;

function cleanMime(m: string | undefined, filename: string): string {
  const s = (m ?? '').toLowerCase().split(';')[0]!.trim();
  if (!s || s === 'application/octet-stream' || !/^[a-z0-9.+-]+\/[a-z0-9.+-]+$/.test(s)) return mimeFromName(filename);
  return s;
}

export function canReadUpload(ctx: Ctx, u: UserRow, up: UploadRow): boolean {
  if (u.role === 'admin' || up.user_id === u.id) return true;
  if (up.project_id && projectRole(ctx.db, u, up.project_id)) return true;
  return false;
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db, cfg } = ctx;

    app.post('/api/uploads', async (req, reply) => {
      const u = requireUser(req);
      if (!req.isMultipart()) throw badRequest('Expected multipart/form-data');
      const created: UploadRow[] = [];
      let projectId: string | null = null;
      try {
        for await (const part of req.parts()) {
          if (part.type === 'field') {
            if (part.fieldname === 'projectId' && typeof part.value === 'string' && part.value) {
              requireProject(db, u, part.value, 'editor');
              projectId = part.value;
            }
            continue;
          }
          const id = crypto.randomUUID();
          const filename = sanitizeFilename(part.filename || 'file');
          const dir = path.join(cfg.uploadsDir, id);
          fs.mkdirSync(dir, { recursive: true });
          const dest = path.join(dir, filename === THUMB ? `_${filename}` : filename);
          try {
            await pipeline(part.file, fs.createWriteStream(dest, { flags: 'wx' }));
          } catch (err) {
            fs.rmSync(dir, { recursive: true, force: true });
            throw err;
          }
          if (part.file.truncated) {
            fs.rmSync(dir, { recursive: true, force: true });
            throw new HttpError(413, 'too_large', 'File exceeds the 50 MB limit');
          }
          const size = fs.statSync(dest).size;
          const mime = cleanMime(part.mimetype, filename);
          let hasThumb = 0;
          if (THUMBABLE.has(mime)) {
            try {
              await sharp(dest, { limitInputPixels: 100_000_000, animated: false })
                .rotate()
                .resize(320, 320, { fit: 'inside', withoutEnlargement: true })
                .webp({ quality: 78 })
                .toFile(path.join(dir, THUMB));
              hasThumb = 1;
            } catch (err) {
              ctx.log.warn({ err: (err as Error).message }, 'thumbnail failed');
            }
          }
          const row: UploadRow = { id, user_id: u.id, project_id: null, filename, mime, size, path: dest, has_thumb: hasThumb, created_at: now() };
          created.push(row);
        }
      } catch (err) {
        for (const r of created) fs.rmSync(path.dirname(r.path), { recursive: true, force: true });
        const e = err as { code?: string };
        if (e.code === 'FST_REQ_FILE_TOO_LARGE') throw new HttpError(413, 'too_large', 'File exceeds the 50 MB limit');
        throw err;
      }
      if (!created.length) throw badRequest('No file in upload', 'no_file');
      const ins = db.prepare(
        `INSERT INTO uploads(id, user_id, project_id, filename, mime, size, path, has_thumb, created_at) VALUES (?,?,?,?,?,?,?,?,?)`,
      );
      db.transaction(() => {
        for (const r of created) {
          r.project_id = projectId;
          ins.run(r.id, r.user_id, r.project_id, r.filename, r.mime, r.size, r.path, r.has_thumb, r.created_at);
        }
      })();
      ctx.audit(req, 'upload', created.map((r) => r.id).join(','), created.map((r) => ({ filename: r.filename, size: r.size, mime: r.mime })));
      reply.code(201);
      const dtos = created.map(attachmentDTO);
      return dtos.length === 1 ? dtos[0] : { ...dtos[0], files: dtos };
    });

    const loadUpload = (req: { params: unknown; user: UserRow | null }) => {
      const u = requireUser(req as never);
      const id = (req.params as { id: string }).id;
      if (!/^[0-9a-f-]{36}$/.test(id)) throw notFound('Upload not found');
      const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get(id) as UploadRow | undefined;
      if (!up) throw notFound('Upload not found');
      if (!canReadUpload(ctx, u, up)) throw notFound('Upload not found');
      // defence in depth: stored path must live under UPLOADS_DIR/<id>/
      const real = fs.existsSync(up.path) ? fs.realpathSync(up.path) : '';
      if (!real || !real.startsWith(fs.realpathSync(path.join(cfg.uploadsDir, up.id)) + path.sep)) throw notFound('Upload file missing');
      return up;
    };

    app.get('/api/uploads/:id', async (req, reply) => {
      const up = loadUpload(req);
      const q = req.query as { download?: string };
      const active = ACTIVE_TYPES.test(up.mime);
      const inline = !active && INLINE_TYPES.test(up.mime) && q.download !== '1';
      reply.header('Content-Type', active ? 'application/octet-stream' : up.mime);
      reply.header('Content-Disposition', contentDisposition(inline ? 'inline' : 'attachment', up.filename));
      reply.header('Content-Security-Policy', "default-src 'none'; img-src 'self' data:; media-src 'self'; style-src 'unsafe-inline'; sandbox");
      reply.header('Cache-Control', 'private, max-age=86400');
      return reply.sendFile(path.basename(up.path), path.dirname(up.path), { contentType: false, cacheControl: false });
    });

    app.get('/api/uploads/:id/thumb', async (req, reply) => {
      const up = loadUpload(req);
      if (!up.has_thumb) throw notFound('No thumbnail');
      reply.header('Content-Type', 'image/webp');
      reply.header('Cache-Control', 'private, max-age=604800');
      return reply.sendFile(THUMB, path.dirname(up.path), { contentType: false, cacheControl: false });
    });

    app.delete('/api/uploads/:id', async (req) => {
      const u = requireUser(req);
      const up = db.prepare(`SELECT * FROM uploads WHERE id = ?`).get((req.params as { id: string }).id) as UploadRow | undefined;
      if (!up) throw notFound('Upload not found');
      if (up.user_id !== u.id && u.role !== 'admin') throw forbidden();
      const referenced = db.prepare(`SELECT 1 FROM messages WHERE attachments LIKE ? LIMIT 1`).get(`%"${up.id}"%`);
      if (referenced) return { ok: true, kept: true }; // referenced by chat history; keep
      db.prepare(`DELETE FROM uploads WHERE id = ?`).run(up.id);
      fs.rmSync(path.join(cfg.uploadsDir, up.id), { recursive: true, force: true });
      return { ok: true };
    });

    // ---- speech-to-text proxy ----
    app.post(
      '/api/transcribe',
      { config: { rateLimit: { max: 30, timeWindow: '1 minute', keyGenerator: (r) => r.user?.id ?? r.clientIp } } },
      async (req) => {
        requireUser(req);
        if (!req.isMultipart()) throw badRequest('Expected multipart/form-data');
        const form = new FormData();
        let gotAudio = false;
        for await (const part of req.parts({ limits: { fileSize: 25 * 1024 * 1024 } })) {
          if (part.type === 'field') {
            if ((part.fieldname === 'language' || part.fieldname === 'prompt') && typeof part.value === 'string' && part.value.length <= 1000)
              form.append(part.fieldname, part.value);
            continue;
          }
          if (gotAudio || (part.fieldname !== 'audio' && part.fieldname !== 'file')) {
            part.file.resume();
            continue;
          }
          const buf = await part.toBuffer().catch((err: { code?: string }) => {
            if (err.code === 'FST_REQ_FILE_TOO_LARGE') throw new HttpError(413, 'too_large', 'Audio too large');
            throw err;
          });
          const type = cleanMime(part.mimetype, part.filename || 'audio.webm');
          form.append('audio', new Blob([new Uint8Array(buf)], { type }), sanitizeFilename(part.filename || 'audio.webm'));
          gotAudio = true;
        }
        if (!gotAudio) throw badRequest('Missing audio', 'no_file');
        let res;
        try {
          res = await request(`${cfg.whisperUrl}/transcribe`, { method: 'POST', body: form, headersTimeout: 120_000, bodyTimeout: 120_000 });
        } catch (err) {
          throw new HttpError(502, 'whisper_unavailable', `Speech-to-text service unavailable: ${(err as Error).message}`);
        }
        const text = await res.body.text();
        if (res.statusCode === 413) throw new HttpError(413, 'too_large', 'Recording is too long or too large to transcribe');
        if (res.statusCode === 422) throw new HttpError(422, 'undecodable_audio', 'Could not decode the recorded audio');
        if (res.statusCode >= 400) throw new HttpError(502, 'whisper_error', `Transcription failed (${res.statusCode})`);
        try {
          const j = JSON.parse(text) as { text?: string; language?: string; durationMs?: number; processingMs?: number };
          return { text: (j.text ?? '').trim(), language: j.language ?? null, durationMs: j.durationMs ?? null, processingMs: j.processingMs ?? null };
        } catch {
          throw new HttpError(502, 'whisper_error', 'Invalid response from speech-to-text service');
        }
      },
    );
  };
import type { FastifyPluginAsync } from 'fastify';
import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { ZipArchive } from 'archiver';
import { z } from 'zod';
import { requireProject, requireUser, type ProjectRow } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { badRequest, conflict, forbidden, notFound } from '../lib/errors.js';
import { contentDisposition, HEAVY_DIRS, looksBinary, mimeFromName, resolveSafe, ZIP_EXCLUDE } from '../lib/safepath.js';
import { branchParam, worktreePath, type BranchRow } from '../lib/branches.js';

const MAX_READ = 2 * 1024 * 1024;
const MAX_TREE_ENTRIES = 5000;
const MAX_DEPTH = 12;

export interface FileNode {
  name: string;
  path: string;
  type: 'file' | 'dir';
  size?: number;
  mtime?: string;
  children?: FileNode[];
  /** heavy dir (node_modules etc.) or depth/size cap: children not loaded; fetch with ?path= */
  lazy?: boolean;
  symlink?: boolean;
}

/** Repo metadata is managed by the workspace (checkpoints/branches): never writable from the editor. */
function noGit(rel: string) {
  if (rel === '.git' || rel.startsWith('.git/')) throw forbidden('The .git folder is managed by the workspace');
}

const pathBody = z.object({ path: z.string().min(1).max(4096) });
const writeBody = z.object({ path: z.string().min(1).max(4096), content: z.string(), encoding: z.enum(['utf8', 'base64']).optional() });
const renameBody = z.object({ from: z.string().min(1).max(4096), to: z.string().min(1).max(4096), overwrite: z.boolean().optional() });

/** Files root of a project (main checkout) or of one of its branches (git worktree). */
export function projectRoot(ctx: Ctx, p: ProjectRow, b?: Pick<BranchRow, 'dir'> | null): string {
  if (b) {
    const wt = worktreePath(ctx.cfg, p.slug, b.dir);
    if (!fs.existsSync(wt)) throw notFound('Branch worktree is missing');
    return wt;
  }
  const root = path.join(ctx.cfg.projectsDir, p.slug);
  fs.mkdirSync(root, { recursive: true });
  return root;
}

async function buildTree(abs: string, rel: string, depth: number, budget: { n: number }): Promise<FileNode[]> {
  let entries: fs.Dirent[];
  try {
    entries = await fsp.readdir(abs, { withFileTypes: true });
  } catch {
    return [];
  }
  entries.sort((a, b) => {
    const ad = a.isDirectory() ? 0 : 1;
    const bd = b.isDirectory() ? 0 : 1;
    return ad - bd || a.name.localeCompare(b.name);
  });
  const out: FileNode[] = [];
  for (const e of entries) {
    if (e.name === '.git') continue; // repo metadata (dir in main, file in worktrees) is never shown
    if (budget.n-- <= 0) break;
    const childRel = rel ? `${rel}/${e.name}` : e.name;
    const childAbs = path.join(abs, e.name);
    if (e.isSymbolicLink()) {
      // never follow symlinks in the tree; show them as files
      out.push({ name: e.name, path: childRel, type: 'file', symlink: true });
      continue;
    }
    if (e.isDirectory()) {
      const node: FileNode = { name: e.name, path: childRel, type: 'dir' };
      if (HEAVY_DIRS.has(e.name) || depth >= MAX_DEPTH || budget.n <= 0) node.lazy = true;
      else node.children = await buildTree(childAbs, childRel, depth + 1, budget);
      out.push(node);
    } else if (e.isFile()) {
      let size: number | undefined;
      let mtime: string | undefined;
      try {
        const st = await fsp.stat(childAbs);
        size = st.size;
        mtime = st.mtime.toISOString();
      } catch {
        /* vanished */
      }
      out.push({ name: e.name, path: childRel, type: 'file', size, mtime });
    }
  }
  return out;
}

async function addDirToZip(zip: ZipArchive, abs: string, rel: string) {
  let entries: fs.Dirent[];
  try {
    entries = await fsp.readdir(abs, { withFileTypes: true });
  } catch {
    return;
  }
  for (const e of entries) {
    const childAbs = path.join(abs, e.name);
    const childRel = rel ? `${rel}/${e.name}` : e.name;
    if (e.isSymbolicLink()) continue; // never follow symlinks
    if (e.isDirectory()) {
      if (ZIP_EXCLUDE.has(e.name)) continue;
      await addDirToZip(zip, childAbs, childRel);
    } else if (e.isFile()) {
      zip.file(childAbs, { name: childRel });
    }
  }
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db } = ctx;
    const proj = (req: Parameters<typeof requireUser>[0], min: 'viewer' | 'editor') => {
      const u = requireUser(req);
      const { project } = requireProject(db, u, (req.params as { id: string }).id, min);
      const branch = branchParam(db, project, (req.query as { branch?: string }).branch);
      return { project, branch, root: projectRoot(ctx, project, branch) };
    };

    app.get('/api/projects/:id/files/tree', async (req) => {
      const { project, branch, root } = proj(req, 'viewer');
      const q = req.query as { path?: string };
      const { rel, abs } = resolveSafe(root, q.path ?? '', { mustExist: true });
      const st = await fsp.stat(abs);
      if (!st.isDirectory()) throw badRequest('Not a directory');
      const budget = { n: MAX_TREE_ENTRIES };
      // Explicitly requested heavy dirs are listed one level deep (lazy children).
      const isHeavy = rel.split('/').some((s) => HEAVY_DIRS.has(s));
      const children = isHeavy ? await shallow(abs, rel) : await buildTree(abs, rel, 0, budget);
      return {
        name: rel ? path.posix.basename(rel) : project.slug,
        branch: branch?.name ?? null,
        path: rel,
        type: 'dir',
        children,
        truncated: budget.n < 0,
      } satisfies FileNode & { truncated: boolean; branch: string | null };
    });

    // NB: paths under '.git' are never served
    async function shallow(abs: string, rel: string): Promise<FileNode[]> {
      const entries = await fsp.readdir(abs, { withFileTypes: true });
      entries.sort((a, b) => (a.isDirectory() ? 0 : 1) - (b.isDirectory() ? 0 : 1) || a.name.localeCompare(b.name));
      return entries.filter((e) => e.name !== '.git').slice(0, MAX_TREE_ENTRIES).map((e) => {
        const p = `${rel}/${e.name}`;
        if (e.isSymbolicLink()) return { name: e.name, path: p, type: 'file' as const, symlink: true };
        return e.isDirectory() ? { name: e.name, path: p, type: 'dir' as const, lazy: true } : { name: e.name, path: p, type: 'file' as const };
      });
    }

    app.get('/api/projects/:id/files/content', async (req) => {
      const { root } = proj(req, 'viewer');
      const q = req.query as { path?: string };
      const { rel, abs } = resolveSafe(root, q.path, { mustExist: true, allowRoot: false });
      const st = await fsp.stat(abs);
      if (st.isDirectory()) throw badRequest('Is a directory', 'is_directory');
      const base = { path: rel, size: st.size, mtime: st.mtime.toISOString() };
      if (st.size > MAX_READ) return { ...base, content: null, binary: false, tooLarge: true };
      const buf = await fsp.readFile(abs);
      if (looksBinary(buf)) return { ...base, content: null, binary: true, mime: mimeFromName(rel) };
      return { ...base, content: buf.toString('utf8'), binary: false };
    });

    app.put('/api/projects/:id/files/content', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = writeBody.parse(req.body);
      const { rel, abs } = resolveSafe(root, body.path, { allowRoot: false });
      noGit(rel);
      const data = body.encoding === 'base64' ? Buffer.from(body.content, 'base64') : Buffer.from(body.content, 'utf8');
      if (data.length > 5 * 1024 * 1024) throw badRequest('File too large', 'too_large');
      try {
        const st = await fsp.lstat(abs);
        if (st.isDirectory()) throw badRequest('Is a directory', 'is_directory');
        if (st.isSymbolicLink()) throw forbidden('Refusing to write through a symlink');
      } catch (err) {
        if ((err as NodeJS.ErrnoException).code !== 'ENOENT') throw err;
      }
      await fsp.mkdir(path.dirname(abs), { recursive: true });
      // re-check parent after mkdir (race with symlink creation)
      resolveSafe(root, path.posix.dirname(rel) === '.' ? '' : path.posix.dirname(rel));
      const tmp = `${abs}.nxtmp-${process.pid}-${Date.now()}`;
      await fsp.writeFile(tmp, data);
      await fsp.rename(tmp, abs);
      const st = await fsp.stat(abs);
      ctx.audit(req, 'file_write', `${project.slug}/${rel}`, { size: data.length });
      return { path: rel, size: st.size, mtime: st.mtime.toISOString() };
    });

    app.post('/api/projects/:id/files/rename', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = renameBody.parse(req.body);
      const from = resolveSafe(root, body.from, { mustExist: true, allowRoot: false, noFollowLeaf: true });
      const to = resolveSafe(root, body.to, { allowRoot: false });
      noGit(from.rel);
      noGit(to.rel);
      if (fs.existsSync(to.abs) && !body.overwrite) throw conflict('Destination already exists', 'exists');
      if ((to.abs + path.sep).startsWith(from.abs + path.sep)) throw badRequest('Cannot move a directory into itself');
      await fsp.mkdir(path.dirname(to.abs), { recursive: true });
      await fsp.rename(from.abs, to.abs);
      ctx.audit(req, 'file_rename', `${project.slug}/${from.rel}`, { to: to.rel });
      return { ok: true, path: to.rel };
    });

    app.post('/api/projects/:id/files/delete', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = pathBody.parse(req.body);
      const { rel, abs } = resolveSafe(root, body.path, { allowRoot: false, noFollowLeaf: true });
      noGit(rel);
      let st: fs.Stats;
      try {
        st = await fsp.lstat(abs);
      } catch {
        throw notFound('No such file or directory');
      }
      // rm on a symlink removes the link, not its target
      await fsp.rm(abs, { recursive: st.isDirectory(), force: true });
      ctx.audit(req, 'file_delete', `${project.slug}/${rel}`);
      return { ok: true };
    });

    app.post('/api/projects/:id/files/mkdir', async (req) => {
      const { project, root } = proj(req, 'editor');
      const body = pathBody.parse(req.body);
      const { rel, abs } = resolveSafe(root, body.path, { allowRoot: false });
      noGit(rel);
      await fsp.mkdir(abs, { recursive: true });
      ctx.audit(req, 'file_mkdir', `${project.slug}/${rel}`);
      return { ok: true, path: rel };
    });

    app.get('/api/projects/:id/files/download', async (req, reply) => {
      const { project, root } = proj(req, 'viewer');
      const q = req.query as { path?: string };
      const { rel, abs } = resolveSafe(root, q.path ?? '', { mustExist: true });
      const st = await fsp.stat(abs);
      if (st.isFile()) {
        const name = path.basename(abs);
        const mime = mimeFromName(name);
        const active = /^(text\/html|image\/svg|application\/xml|text\/javascript)/.test(mime);
        const inline = (req.query as { inline?: string }).inline === '1' && !active;
        // Correct content-type so <img src> previews work; active types are sandboxed and never rendered inline.
        reply.header('Content-Type', mime.startsWith('text/') ? `${mime}; charset=utf-8` : mime);
        reply.header('Content-Disposition', contentDisposition(inline ? 'inline' : 'attachment', name));
        reply.header('Content-Security-Policy', "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox");
        reply.header('Cache-Control', 'no-cache');
        reply.header('Content-Length', st.size);
        return reply.send(fs.createReadStream(abs));
      }
      const zipName = `${rel ? path.posix.basename(rel) : project.slug}.zip`;
      const zip = new ZipArchive({ zlib: { level: 6 } });
      zip.on('warning', (err) => ctx.log.warn({ err: err.message }, 'zip warning'));
      zip.on('error', (err) => {
        ctx.log.error({ err: err.message }, 'zip error');
        reply.raw.destroy(err);
      });
      reply.header('Content-Type', 'application/zip');
      reply.header('Content-Disposition', contentDisposition('attachment', zipName));
      await addDirToZip(zip, abs, '');
      void zip.finalize();
      return reply.send(zip);
    });
  };

