export function buildSystemPrompt(
  project: ProjectRow,
  cfg: Config,
  agents: { slug: string; description: string }[] = [],
  branch: Pick<BranchRow, 'name' | 'dir' | 'base' | 'preview_port'> | null = null,
): string {
  const cwd = claudeboxCwd(cfg, project.slug, branch);
  const base = previewPath(project.slug, branch);
  const port = branch ? branch.preview_port : project.preview_port;
  const lines = [
    `You are working inside the Nxeon Workspace on the project "${project.name}".`,
    project.description ? `Project description: ${project.description}` : '',
    `Project directory (your cwd): ${cwd}. Keep all work inside this directory.`,
    branch
      ? `You are on git branch "${branch.name}" (a separate worktree created from "${branch.base}"); the main checkout lives elsewhere — never modify it.`
      : '',
    'The folder is a git repo; the workspace commits an automatic checkpoint after every run. Do not commit, rebase, reset, stash or switch branches unless the user asks.',
    `Assigned preview port: ${port}. When you start a dev/preview server, bind it to 0.0.0.0 and use exactly this port (set PORT=${port} HOST=0.0.0.0).`,
    project.preview_strip
      ? `The preview is shown to the user at ${cfg.publicUrl}${base} (the proxy strips this prefix, so the app can be served from /).`
      : `The preview is shown to the user at ${cfg.publicUrl}${base}. Configure the app's base path to "${base}" (e.g. Vite \`base: '${base}'\`, Next.js \`basePath: '${base.replace(/\/$/, '')}'\`), and make asset/HMR URLs relative to it. The env var BASE_PATH=${base} is set for preview servers.`,
    `Run long-lived servers in the background (e.g. with nohup ... &) so your turn can finish; the user's preview pane connects to the port.`,
    '',
    'TOKEN BUDGET — be economical; the user pays per token:',
    '- Pick the simplest approach that fully satisfies the request. Simple sites/pages: plain index.html + CSS/JS, no framework, no npm, no build step, unless the user asks for one or it is clearly required.',
    '- The workspace previews projects automatically (static files are served as-is; package.json dev servers are started for the user). Do NOT start servers, curl the preview, take screenshots, or look for browser tooling unless the user explicitly asks.',
    '- Use as few tool calls as possible: read only files you need, do not re-read files you just wrote, prefer one Write over many Edits for new files, skip exploratory commands, no subagents for small tasks.',
    '- Do not run builds, tests or type-checks for trivial changes unless asked.',
    '- Keep the final reply short: a few lines on what changed. No long recaps, tables, or repeating code the user can see in the editor.',
    `You have internet access (npm, pip, git, web).`,
    `Keep a concise, up-to-date README.md in the project root describing what the project is and how to run it.`,
    `Uploaded attachments are available read-only under ${cfg.claudeboxUploadsDir}/.`,
    ...(agents.length
      ? [
          '',
          'SUBAGENTS available via the Agent tool (subagent_type = name):',
          ...agents.map((a) => `- ${a.slug}: ${a.description.replace(/\s+/g, ' ').slice(0, 300)}`),
          'Delegate to a subagent only when it clearly saves effort (parallel research, independent review, large isolated tasks); do small tasks yourself.',
          'Exception: when the user writes @<name> (e.g. @researcher), delegate that part to exactly that subagent (subagent_type "<name>"), even for small tasks.',
        ]
      : []),
    '',
    'At the very end of EVERY final reply, append 2-3 short actionable follow-up suggestions for the user in exactly this format (valid JSON array on one line, no code fences):',
    '<nx-suggestions>[{"label":"Short button text","prompt":"The full prompt to send if clicked","kind":"next"}]</nx-suggestions>',
    'kind must be one of: next, fix, test, deploy, explain. The block is hidden from the user and rendered as clickable chips. Never mention it.',
  ];
  return lines.filter((l) => l !== '').join('\n');
}

export class RunManager {
  private active = new Map<string, ActiveRun>();
  private flushTimer: NodeJS.Timeout | null = null;
  private lastPulse = new Map<string, number>();
  private insertEvent;
  private updateRunTotals;

  constructor(
    private db: DB,
    private hub: Hub,
    private cb: Claudebox,
    private cfg: Config,
    private settings: Settings,
    private log: FastifyBaseLogger,
  ) {
    this.insertEvent = db.prepare(`INSERT OR IGNORE INTO run_events(run_id, seq, type, data, ts) VALUES (?,?,?,?,?)`);
    this.updateRunTotals = db.prepare(
      `UPDATE runs SET input_tokens=?, output_tokens=?, cache_read=?, cache_write=?, cost_usd=?, upstream_seq=? WHERE id=?`,
    );
  }

  isActive(runId: string) {
    return this.active.has(runId);
  }
  activeIds() {
    return [...this.active.keys()];
  }
  activeForConversation(conversationId: string): string | null {
    for (const r of this.active.values()) if (r.conversationId === conversationId) return r.id;
    return null;
  }

  /** Events from DB + in-memory pending, seq >= fromSeq. Synchronous so the caller can subscribe without gaps. */
  replay(runId: string, fromSeq: number): StoredEvent[] {
    const rows = this.db
      .prepare(`SELECT seq, type, data, ts FROM run_events WHERE run_id = ? AND seq >= ? ORDER BY seq`)
      .all(runId, fromSeq) as { seq: number; type: string; data: string; ts: number }[];
    const out: StoredEvent[] = rows.map((r) => ({ seq: r.seq, type: r.type, data: parseJson(r.data, null), ts: r.ts }));
    const a = this.active.get(runId);
    if (a) {
      const maxDb = out.length ? out[out.length - 1]!.seq : fromSeq - 1;
      for (const e of a.pending) if (e.seq > maxDb && e.seq >= fromSeq) out.push(e);
    }
    return out;
  }

  // ---------------- lifecycle ----------------

  start(p: {
    runId: string;
    conversationId: string;
    projectId: string;
    userId: string;
    assistantMessageId: string;
    body: V2RunBody;
    kind?: 'compact' | null;
    branch?: string | null;
  }) {
    const run = this.newState(p.runId, p.conversationId, p.projectId, p.userId, p.assistantMessageId, p.body);
    run.kind = p.kind ?? null;
    run.branch = p.branch ?? null;
    this.active.set(run.id, run);
    void this.drive(run, false);
  }

  private newState(
    id: string,
    conversationId: string,
    projectId: string,
    userId: string | null,
    assistantMessageId: string,
    body: V2RunBody | null,
  ): ActiveRun {
    return {
      id, conversationId, projectId, userId, assistantMessageId, body,
      seq: 0, upstreamSeq: 0, pending: [], fullText: '', emittedLen: 0, needSep: false,
      usage: { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 },
      costUsd: 0, sessionCostUsd: null, durationMs: null, sawResult: false, resultIsError: false, resultText: '', sawError: false,
      lastError: null, exitCode: undefined, abortRequested: false, ended: false, controller: new AbortController(),
      startedAt: now(),
      kind: null,
      branch: null,
    };
  }

  private setStatus(run: ActiveRun, status: RunStatus) {
    this.db.prepare(`UPDATE runs SET status = ? WHERE id = ?`).run(status, run.id);
    this.hub.broadcastViewers(run.projectId, { t: 'run_status', runId: run.id, conversationId: run.conversationId, projectId: run.projectId, status, branch: run.branch });
  }

  /** Connects (or re-attaches) to claudebox and consumes the stream until `done` or give-up. */
  private async drive(run: ActiveRun, recovering: boolean) {
    if (!recovering) {
      this.setStatus(run, 'running');
      this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(now(), run.projectId);
    }
    let attempt = 0;
    let first = !recovering;
    while (!run.ended) {
      if (run.abortRequested && first) {
        this.synthEnd(run, null);
        return;
      }
      let res: Dispatcher.ResponseData;
      try {
        res = first ? await this.cb.startRun(run.body!, run.controller.signal) : await this.cb.attach(run.id, run.upstreamSeq + 1, run.controller.signal);
      } catch (err) {
        if (run.ended) return;
        if (run.abortRequested) {
          this.synthEnd(run, null);
          return;
        }
        if (first) {
          this.emit(run, 'error', { message: `Cannot reach claudebox: ${(err as Error).message}` });
          this.synthEnd(run, null);
          return;
        }
        if (++attempt > (recovering ? 2 : MAX_REATTACH)) {
          this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
          this.synthEnd(run, null);
          return;
        }
        await sleep(Math.min(8000, 500 * 2 ** attempt));
        continue;
      }
      const wasFirst = first;
      first = false;
      if (res.statusCode !== 200) {
        const text = (await res.body.text().catch(() => '')).slice(0, 500);
        if (run.ended) return;
        if (!wasFirst && res.statusCode === 404) {
          this.emit(run, 'error', { message: recovering ? 'The run was lost while the server restarted.' : 'Lost connection to the Claude runner (run no longer available).' });
        } else {
          let msg = text;
          try {
            const j = JSON.parse(text) as { error?: unknown; message?: unknown };
            const e = j.error ?? j.message;
            msg = typeof e === 'string' ? e : (e as { message?: string })?.message ?? text;
          } catch {
            /* plain text */
          }
          this.emit(run, 'error', { message: `Claude runner error (${res.statusCode}): ${msg || 'unknown error'}` });
        }
        this.synthEnd(run, null);
        return;
      }
      attempt = 0;
      try {
        await this.consume(run, res.body);
      } catch (err) {
        if (run.ended) return;
        this.log.warn({ runId: run.id, err: (err as Error).message }, 'run stream interrupted');
      }
      if (run.ended) return;
      if (run.abortRequested && run.controller.signal.aborted) {
        this.synthEnd(run, null);
        return;
      }
      // Stream ended without `done` → reattach with backoff.
      if (++attempt > MAX_REATTACH) {
        this.emit(run, 'error', { message: 'Lost connection to the Claude runner.' });
        this.synthEnd(run, null);
        return;
      }
      await sleep(Math.min(8000, 300 * 2 ** attempt));
    }
  }

  private async consume(run: ActiveRun, body: Dispatcher.ResponseData['body']) {
    const parser = new SseParser();
    body.setEncoding('utf8');
    for await (const chunk of body) {
      for (const m of parser.push(chunk as string)) {
        this.handleUpstream(run, m);
        if (run.ended) {
          body.destroy();
          return;
        }
      }
    }
  }

  handleUpstream(run: ActiveRun, m: SseMessage) {
    if (m.id !== undefined && /^\d+$/.test(m.id)) {
      const id = Number(m.id);
      if (id <= run.upstreamSeq) return; // duplicate after reattach
      run.upstreamSeq = id;
    }
    const type = m.event as RunEventType;
    if (!KNOWN_TYPES.has(type)) return;
    let data: Record<string, unknown>;
    try {
      data = (m.data ? JSON.parse(m.data) : {}) as Record<string, unknown>;
    } catch {
      return;
    }
    switch (type) {
      case 'init': {
        const sid = typeof data.sessionId === 'string' ? data.sessionId : null;
        if (sid) this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(sid, run.conversationId);
        this.emit(run, 'init', data);
        break;
      }
      case 'text': {
        if (typeof data.parentId === 'string') {
          // forwarded subagent text: shown under the delegating tool, never part of the answer
          this.emit(run, 'text', data);
          break;
        }
        let delta = typeof data.delta === 'string' ? data.delta : '';
        if (!delta) return;
        if (run.needSep && run.fullText.length && !/\n\s*$/.test(run.fullText)) delta = '\n\n' + delta;
        run.needSep = false;
        run.fullText += delta;
        this.emitVisible(run, true);
        break;
      }
      case 'block_end': {
        if (data.kind === 'text') {
          this.emitVisible(run, false);
          run.needSep = true;
        }
        this.emit(run, 'block_end', data);
        break;
      }
      case 'usage': {
        const u = data as Partial<Usage>;
        run.usage.inputTokens += num(u.inputTokens);
        run.usage.outputTokens += num(u.outputTokens);
        run.usage.cacheReadTokens += num(u.cacheReadTokens);
        run.usage.cacheWriteTokens += num(u.cacheWriteTokens);
        if (!data.parentId && num(data.contextTokens) > 0) this.setContextTokens(run, num(data.contextTokens));
        this.emit(run, 'usage', data);
        break;
      }
      case 'compact': {
        this.setContextTokens(run, num(data.postTokens));
        this.emit(run, 'compact', data);
        break;
      }
      case 'result': {
        run.sawResult = true;
        run.resultIsError = !!data.isError;
        run.resultText = typeof data.result === 'string' ? data.result : '';
        const u = data.usage as Partial<Usage> | undefined;
        if (u && typeof u === 'object') {
          // result.usage covers the main thread only; the summed usage events also include subagents
          // (parentId) and estimated compaction usage — keep whichever is larger per field.
          run.usage = {
            inputTokens: Math.max(num(u.inputTokens), run.usage.inputTokens),
            outputTokens: Math.max(num(u.outputTokens), run.usage.outputTokens),
            cacheReadTokens: Math.max(num(u.cacheReadTokens), run.usage.cacheReadTokens),
            cacheWriteTokens: Math.max(num(u.cacheWriteTokens), run.usage.cacheWriteTokens),
          };
        }
        if (typeof data.costUsd === 'number') {
          // total_cost_usd is cumulative for the resumed session: charge this run only the increase.
          const prev = (this.db
            .prepare(`SELECT COALESCE(MAX(session_cost_usd), 0) AS v FROM runs WHERE conversation_id = ? AND id != ? AND started_at <= ?`)
            .get(run.conversationId, run.id, run.startedAt) as { v: number }).v;
          run.sessionCostUsd = data.costUsd;
          run.costUsd = data.costUsd >= prev ? data.costUsd - prev : data.costUsd;
        }
        if (typeof data.durationMs === 'number') run.durationMs = data.durationMs;
        if (typeof data.sessionId === 'string' && data.sessionId)
          this.db.prepare(`UPDATE conversations SET claude_session_id = ? WHERE id = ?`).run(data.sessionId, run.conversationId);
        if (run.resultIsError && run.resultText && !run.lastError) run.lastError = run.resultText;
        // The suggestions block lives in the final text; don't leak it through the result payload.
        this.emit(run, 'result', { ...data, result: finalContent(run.resultText) });
        break;
      }
      case 'error': {
        run.sawError = true;
        if (data.code === 'authentication_failed') {
          data = { ...data, detail: data.message, message: AUTH_HINT };
        }
        run.lastError = typeof data.message === 'string' ? data.message : 'error';
        this.emit(run, 'error', data);
        break;
      }
      case 'done': {
        this.emitVisible(run, false);
        run.exitCode = typeof data.exitCode === 'number' ? data.exitCode : null;
        if (data.aborted === true) run.abortRequested = true;
        this.emit(run, 'done', { ...data, exitCode: run.exitCode });
        this.finalize(run);
        break;
      }
      default:
        this.emit(run, type, data);
    }
  }

  private setContextTokens(run: ActiveRun, n: number) {
    if (!(n >= 0)) return;
    this.db.prepare(`UPDATE conversations SET context_tokens = ? WHERE id = ?`).run(Math.round(n), run.conversationId);
  }

  private emitVisible(run: ActiveRun, holdPartial: boolean) {
    const vis = visibleText(run.fullText, holdPartial);
    if (vis.length > run.emittedLen) {
      this.emit(run, 'text', { delta: vis.slice(run.emittedLen) });
      run.emittedLen = vis.length;
    }
  }

  private emit(run: ActiveRun, type: string, data: unknown) {
    const seq = ++run.seq;
    const ts = now();
    const ev: StoredEvent = { seq, type, data, ts };
    run.pending.push(ev);
    // `ts` is an additive field (not in protocol.ts) used by the UI for "Thought for Xs".
    this.hub.broadcastRun(run.id, { t: 'run_event', runId: run.id, seq, type, data, ts } as never);
    this.pulse(run.projectId, PULSE[type as RunEventType] ?? 0.2, run.branch);
    if (!this.flushTimer) this.flushTimer = setTimeout(() => this.flushAll(), FLUSH_MS);
  }

  private pulse(projectId: string, intensity: number, branch: string | null = null) {
    const t = Date.now();
    const k = `${projectId}|${branch ?? ''}`;
    if (intensity < 0.8 && t - (this.lastPulse.get(k) ?? 0) < 250) return;
    this.lastPulse.set(k, t);
    this.hub.broadcastViewers(projectId, { t: 'graph_pulse', projectId, intensity, branch });
  }

  flushAll() {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    const tx = this.db.transaction(() => {
      for (const run of this.active.values()) this.flushRun(run);
    });
    try {
      tx();
    } catch (err) {
      this.log.error({ err }, 'flush run events failed');
    }
  }

  private flushRun(run: ActiveRun) {
    if (!run.pending.length) return;
    for (const e of run.pending) this.insertEvent.run(run.id, e.seq, e.type, JSON.stringify(e.data ?? null), e.ts);
    run.pending = [];
    this.updateRunTotals.run(
      run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
      run.costUsd, run.upstreamSeq, run.id,
    );
  }

  /** Emit a synthetic `done` and finalize (used on errors / aborts without upstream completion). */
  private synthEnd(run: ActiveRun, exitCode: number | null) {
    if (run.ended) return;
    this.emitVisible(run, false);
    run.exitCode = exitCode;
    this.emit(run, 'done', { exitCode });
    this.finalize(run);
  }

  private finalize(run: ActiveRun) {
    if (run.ended) return;
    run.ended = true;
    run.controller.abort();
    let status: RunStatus;
    if (run.abortRequested) status = 'aborted';
    else if (run.sawResult) status = run.resultIsError ? 'error' : 'done';
    else if (run.sawError) status = 'error';
    else status = run.exitCode === 0 ? 'done' : 'error';

    let suggestions: Suggestion[] = parseSuggestions(run.fullText);
    if (!suggestions.length && run.resultText) suggestions = parseSuggestions(run.resultText);
    let content = finalContent(run.fullText);
    if (!content && run.resultText) content = finalContent(run.resultText);
    const t = now();
    const durationMs = run.durationMs ?? t - run.startedAt;

    this.db.transaction(() => {
      this.flushRun(run);
      this.updateRunTotals.run(
        run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
        run.costUsd, run.upstreamSeq, run.id,
      );
      this.db
        .prepare(`UPDATE runs SET status = ?, ended_at = ?, duration_ms = ?, error = ?, session_cost_usd = ? WHERE id = ?`)
        .run(status, t, durationMs, status === 'error' ? (run.lastError ?? 'Run failed').slice(0, 2000) : null, run.sessionCostUsd, run.id);
      this.db
        .prepare(`UPDATE messages SET content = ?, suggestions = ? WHERE id = ?`)
        .run(content, suggestions.length ? JSON.stringify(suggestions) : null, run.assistantMessageId);
      this.db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, run.conversationId);
      this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(t, run.projectId);
    })();
    this.active.delete(run.id);
    if (suggestions.length) this.hub.broadcastRun(run.id, { t: 'suggestions', runId: run.id, items: suggestions });
    this.hub.broadcastViewers(run.projectId, { t: 'run_status', runId: run.id, conversationId: run.conversationId, projectId: run.projectId, status, branch: run.branch });
    this.pulse(run.projectId, 1, run.branch);
    if (status === 'done' && run.kind !== 'compact') {
      void this.checkpoint(run).finally(() => this.autoStartPreview(run.projectId, run.branch));
    }
  }

  /** Auto-checkpoint: commit everything in the run's checkout as "nxeon: <prompt>" and record the sha on the run. */
  private async checkpoint(run: ActiveRun) {
    try {
      const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(run.projectId) as ProjectRow | undefined;
      if (!p) return;
      const b = run.branch ? getBranch(this.db, p.id, run.branch) : null;
      if (run.branch && !b) return;
      const main = await ensureGit({ db: this.db, cb: this.cb, log: this.log }, p);
      const prompt = run.body?.prompt
        ?? (this.db.prepare(`SELECT content FROM messages WHERE run_id = ? AND role = 'user'`).get(run.id) as { content: string } | undefined)?.content
        ?? '';
      const line = prompt.replace(/\s+/g, ' ').trim().slice(0, 60) || 'run';
      const r = await this.cb.git<{ sha: string | null; skipped?: string }>('checkpoint', {
        projectSlug: p.slug, ...(b ? { worktree: b.dir } : {}), message: `nxeon: ${line}`, expectBranch: b ? b.name : main,
      });
      if (r.skipped) this.log.warn({ runId: run.id, skipped: r.skipped }, 'checkpoint skipped');
      if (r.sha) {
        this.db.prepare(`UPDATE runs SET commit_sha = ? WHERE id = ?`).run(r.sha, run.id);
        this.hub.broadcastProject(p.id, { t: 'project_changed', projectId: p.id, what: 'history', branch: run.branch });
      }
      if (b) {
        const st = await this.cb.git<{ branches: { worktree: string; ahead?: number; behind?: number; filesChanged?: number }[] }>('status', {
          projectSlug: p.slug, branches: [{ worktree: b.dir, base: b.base }],
        });
        const x = st.branches?.[0];
        if (x && x.filesChanged != null)
          this.db.prepare(`UPDATE branches SET ahead = ?, behind = ?, files_changed = ?, stat_at = ? WHERE id = ?`).run(x.ahead ?? 0, x.behind ?? 0, x.filesChanged, now(), b.id);
      }
    } catch (err) {
      this.log.warn({ err: (err as Error).message, runId: run.id }, 'auto-checkpoint failed');
    }
  }

  /** Start the preview after a successful run if the checkout looks servable and nothing is running yet. */
  async autoStartPreview(projectId: string, branch: string | null = null) {
    try {
      const p = this.db.prepare(`SELECT * FROM projects WHERE id = ?`).get(projectId) as ProjectRow | undefined;
      if (!p) return;
      const b = branch ? getBranch(this.db, p.id, branch) : null;
      if (branch && !b) return;
      const dir = b ? worktreePath(this.cfg, p.slug, b.dir) : path.join(this.cfg.projectsDir, p.slug);
      const port = b ? b.preview_port : p.preview_port;
      if (!['index.html', 'package.json'].some((f) => fs.existsSync(path.join(dir, f)))) return;
      const cur = await this.cb.previewStatus(p.slug, port, b?.dir);
      if (cur.running) return;
      const s = await this.cb.previewStart(p.slug, port, p.preview_command, b?.dir);
      this.hub.broadcastProject(p.id, { t: 'preview_status', projectId: p.id, running: !!s.running, port: s.port ?? port, branch });
    } catch (err) {
      this.log.warn({ err: (err as Error).message, projectId, branch }, 'preview auto-start failed');
    }
  }

  // ---------------- abort ----------------

  async abort(runId: string): Promise<boolean> {
    const run = this.active.get(runId);
    if (!run) {
      // orphan (e.g. not driven by this process): mark aborted directly
      const r = this.db.prepare(`SELECT status FROM runs WHERE id = ?`).get(runId) as { status: RunStatus } | undefined;
      if (r && (r.status === 'running' || r.status === 'queued')) {
        this.db.prepare(`UPDATE runs SET status = 'aborted', ended_at = ? WHERE id = ?`).run(now(), runId);
        return true;
      }
      return false;
    }
    if (run.ended) return false;
    run.abortRequested = true;
    try {
      await this.cb.abort(runId);
    } catch (err) {
      this.log.warn({ runId, err: (err as Error).message }, 'claudebox abort failed');
    }
    setTimeout(() => {
      if (!run.ended) {
        run.controller.abort();
        this.synthEnd(run, null);
      }
    }, ABORT_GRACE_MS).unref();
    return true;
  }

  // ---------------- recovery ----------------

  /** On startup: re-attach to runs left running by a previous process, or mark them as errored. */
  recoverOrphans() {
    const rows = this.db
      .prepare(
        `SELECT r.id, r.conversation_id, r.project_id, r.user_id, r.upstream_seq, r.input_tokens, r.output_tokens, r.cache_read,
                r.cache_write, r.cost_usd, r.started_at, r.branch, m.id AS message_id
         FROM runs r LEFT JOIN messages m ON m.run_id = r.id AND m.role = 'assistant'
         WHERE r.status IN ('queued','running')`,
      )
      .all() as {
      id: string; conversation_id: string; project_id: string; user_id: string | null; upstream_seq: number;
      input_tokens: number; output_tokens: number; cache_read: number; cache_write: number; cost_usd: number;
      started_at: number; branch: string | null; message_id: string | null;
    }[];
    for (const r of rows) {
      if (this.active.has(r.id)) continue;
      const run = this.newState(r.id, r.conversation_id, r.project_id, r.user_id, r.message_id ?? '', null);
      run.startedAt = r.started_at;
      run.branch = r.branch;
      run.upstreamSeq = r.upstream_seq;
      run.usage = { inputTokens: r.input_tokens, outputTokens: r.output_tokens, cacheReadTokens: r.cache_read, cacheWriteTokens: r.cache_write };
      run.costUsd = r.cost_usd;
      const evs = this.db.prepare(`SELECT seq, type, data FROM run_events WHERE run_id = ? ORDER BY seq`).all(r.id) as {
        seq: number; type: string; data: string;
      }[];
      for (const e of evs) {
        run.seq = e.seq;
        const d = parseJson<Record<string, unknown>>(e.data, {});
        if (e.type === 'text' && typeof d.delta === 'string' && !d.parentId) {
          run.fullText += d.delta;
          run.needSep = false;
        } else if (e.type === 'block_end' && d.kind === 'text') run.needSep = true;
        else if (e.type === 'error') {
          run.sawError = true;
          run.lastError = String(d.message ?? 'error');
        }
      }
      run.emittedLen = run.fullText.length;
      this.active.set(run.id, run);
      this.log.info({ runId: r.id }, 'recovering orphaned run');
      void this.drive(run, true);
    }
  }

  /** Graceful shutdown: flush pending events; leave runs as running so the next start can re-attach. */
  shutdown() {
    this.flushAll();
    for (const run of this.active.values()) {
      run.ended = true; // stop drive loops without finalizing
      run.controller.abort();
    }
  }
}

function num(v: unknown): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : 0;
}
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

"use strict";
// Git layer for Nxeon "branches": every project dir is a git repo; a branch is a git worktree at
// <projectsDir>/.branches/<slug>/<worktree>. All git commands for the app run here (claudebox has git
// and owns the files as uid 1000; worktree metadata stores absolute paths, which must be the paths
// Claude sees, i.e. /workspace/projects/...).

const { execFile } = require("child_process");
const fs = require("fs");
const os = require("os");
const path = require("path");
const crypto = require("crypto");

const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const WORKTREE_RE = /^[a-z0-9][a-z0-9_-]{0,63}$/;
/** Branches we create: lowercase segments joined by single '-' or '/', no '--' (reserved for preview keys). */
const BRANCH_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*(?:\/[a-z0-9]+(?:-[a-z0-9]+)*)*$/;
/** Any ref name we accept as input (e.g. an adopted repo's "master"). */
const REF_RE = /^(?!-)(?!.*\.\.)(?!.*\/\/)(?!.*@\{)[A-Za-z0-9._/-]{1,100}$/;
const SHA_RE = /^[0-9a-f]{7,40}$/;
const GITIGNORE = ["node_modules", "dist", ".next", ".venv", "__pycache__", ".DS_Store"];
const MAX_FILE = 1024 * 1024;

class GitError extends Error {
  constructor(status, message, extra) {
    super(message);
    this.status = status;
    this.extra = extra || {};
  }
}

function isInside(root, p) {
  const rel = path.relative(root, p);
  return rel === "" || (!rel.startsWith("..") && !path.isAbsolute(rel));
}

function cleanRelPath(p) {
  if (typeof p !== "string" || !p || p.length > 4096 || p.includes("\0")) throw new GitError(400, "Invalid path");
  const norm = path.posix.normalize(p.replace(/\\/g, "/").replace(/^\/+/, ""));
  if (!norm || norm === "." || norm.startsWith("../") || norm === ".." || path.posix.isAbsolute(norm)) throw new GitError(400, "Invalid path");
  return norm;
}

function looksBinary(buf) {
  return buf.subarray(0, 8192).includes(0);
}

class GitManager {
  constructor(config = {}) {
    this.config = { projectsDir: "/workspace/projects", timeoutMs: 120000, log: () => {}, ...config };
    this.locks = new Map();
  }

  repoDir(slug) {
    return path.join(this.config.projectsDir, slug);
  }
  worktreeDir(slug, wt) {
    return path.join(this.config.projectsDir, ".branches", slug, wt);
  }
  /** Directory for a target: the repo itself (main) or a branch worktree. */
  dirFor(slug, worktree) {
    const d = worktree ? this.worktreeDir(slug, worktree) : this.repoDir(slug);
    if (!fs.existsSync(d)) throw new GitError(404, worktree ? `Worktree '${worktree}' not found` : "Project directory not found");
    return d;
  }

  /** Serialize git operations per repository. */
  lock(slug, fn) {
    const prev = this.locks.get(slug) || Promise.resolve();
    const next = prev.catch(() => {}).then(fn);
    const tail = next.catch(() => {});
    this.locks.set(slug, tail);
    tail.then(() => {
      if (this.locks.get(slug) === tail) this.locks.delete(slug);
    });
    return next;
  }

  git(cwd, args, opts = {}) {
    const env = {
      ...process.env,
      GIT_TERMINAL_PROMPT: "0",
      GIT_OPTIONAL_LOCKS: "0",
      LC_ALL: "C",
      ...(opts.env || {}),
    };
    for (const k of ["CLAUDEBOX_API_KEY", "CLAUDE_CODE_OAUTH_TOKEN", "ANTHROPIC_API_KEY", "GIT_DIR", "GIT_WORK_TREE"]) delete env[k];
    const full = ["-c", "core.hooksPath=/dev/null", "-c", "core.quotepath=false", "-c", "commit.gpgsign=false", ...args];
    return new Promise((resolve, reject) => {
      execFile(
        "git",
        full,
        { cwd, env, maxBuffer: 64 * 1024 * 1024, timeout: opts.timeoutMs || this.config.timeoutMs, encoding: opts.encoding || "utf8" },
        (err, stdout, stderr) => {
          const code = err ? (typeof err.code === "number" ? err.code : 1) : 0;
          if (err && typeof err.code !== "number" && !opts.allowFail) {
            return reject(new GitError(500, `git ${args[0]} failed: ${err.message}`));
          }
          if (code !== 0 && !opts.allowFail) {
            return reject(new GitError(500, `git ${args.join(" ").slice(0, 120)} failed: ${String(stderr || stdout).trim().slice(0, 500)}`));
          }
          resolve({ code, stdout, stderr: String(stderr || "") });
        },
      );
    });
  }

  async currentBranch(dir) {
    const r = await this.git(dir, ["symbolic-ref", "--short", "-q", "HEAD"], { allowFail: true });
    return r.code === 0 ? r.stdout.trim() : null;
  }
  async headSha(dir) {
    const r = await this.git(dir, ["rev-parse", "-q", "--verify", "HEAD^{commit}"], { allowFail: true });
    return r.code === 0 ? r.stdout.trim() : null;
  }
  async refExists(dir, ref) {
    const r = await this.git(dir, ["show-ref", "--verify", "-q", `refs/heads/${ref}`], { allowFail: true });
    return r.code === 0;
  }

  // ---------------------------------------------------------------- ensure

  /** Make sure the project dir is a git repo with at least one commit. Adopts an existing repo. */
  ensure(slug) {
    return this.lock(slug, () => this._ensure(slug));
  }
  async _ensure(slug) {
    const dir = this.repoDir(slug);
    fs.mkdirSync(dir, { recursive: true });
    let initialized = false;
    let adopted = false;
    const hasGit = fs.existsSync(path.join(dir, ".git"));
    if (hasGit) {
      const top = await this.git(dir, ["rev-parse", "--show-toplevel"], { allowFail: true });
      if (top.code !== 0 || path.resolve(top.stdout.trim()) !== fs.realpathSync(dir)) {
        throw new GitError(409, "Project .git is not a usable repository");
      }
      adopted = true;
    } else {
      await this.git(dir, ["init", "-q", "-b", "main"]);
      initialized = true;
    }
    await this.git(dir, ["config", "user.name", "Nxeon"]);
    await this.git(dir, ["config", "user.email", "nxeon@workspace.local"]);
    this._ensureGitignore(dir);
    let main = await this.currentBranch(dir);
    if (!main) {
      // detached HEAD in an adopted repo: give it a branch so checkpoints have somewhere to go
      main = (await this.refExists(dir, "main")) ? `nxeon-main-${crypto.randomBytes(2).toString("hex")}` : "main";
      await this.git(dir, ["checkout", "-q", "-b", main]);
    }
    let head = await this.headSha(dir);
    if (!head) {
      await this.git(dir, ["add", "-A"]);
      await this.git(dir, ["commit", "-q", "--no-verify", "--allow-empty", "-m", "nxeon: initial snapshot"]);
      head = await this.headSha(dir);
      initialized = true;
    }
    await this.git(dir, ["worktree", "prune"], { allowFail: true });
    if (initialized || adopted) this.config.log("info", "git ensured", { slug, main, initialized, adopted });
    return { mainBranch: main, head, initialized, adopted };
  }

  _ensureGitignore(dir) {
    const f = path.join(dir, ".gitignore");
    let cur = "";
    try {
      cur = fs.readFileSync(f, "utf8");
    } catch {
      /* none */
    }
    const have = new Set(cur.split(/\r?\n/).map((l) => l.trim().replace(/^\/+|\/+$/g, "")));
    const missing = GITIGNORE.filter((e) => !have.has(e));
    if (!missing.length) return;
    const sep = cur && !cur.endsWith("\n") ? "\n" : "";
    fs.writeFileSync(f, cur + sep + missing.join("\n") + "\n");
  }

  // ---------------------------------------------------------------- branches

  async createBranch(slug, { branch, worktree, base }) {
    if (!BRANCH_RE.test(branch || "") || branch.length > 60) throw new GitError(400, "Invalid branch name");
    if (!WORKTREE_RE.test(worktree || "")) throw new GitError(400, "Invalid worktree");
    if (!REF_RE.test(base || "")) throw new GitError(400, "Invalid base");
    return this.lock(slug, async () => {
      const repo = this.dirFor(slug, null);
      const wt = this.worktreeDir(slug, worktree);
      if (fs.existsSync(wt)) throw new GitError(409, `Worktree directory already exists`);
      if (!(await this.refExists(repo, base))) throw new GitError(404, `Base branch '${base}' not found`);
      fs.mkdirSync(path.dirname(wt), { recursive: true });
      await this.git(repo, ["worktree", "prune"], { allowFail: true });
      const exists = await this.refExists(repo, branch);
      if (exists) await this.git(repo, ["worktree", "add", "-q", wt, branch]);
      else await this.git(repo, ["worktree", "add", "-q", "-b", branch, wt, base]);
      return { ok: true, head: await this.headSha(wt), adoptedRef: exists, path: wt };
    });
  }

  async removeBranch(slug, { branch, worktree, deleteRef = true }) {
    if (!WORKTREE_RE.test(worktree || "")) throw new GitError(400, "Invalid worktree");
    if (branch != null && !REF_RE.test(branch)) throw new GitError(400, "Invalid branch");
    return this.lock(slug, async () => {
      const repo = this.dirFor(slug, null);
      const wt = this.worktreeDir(slug, worktree);
      if (fs.existsSync(wt)) {
        const r = await this.git(repo, ["worktree", "remove", "--force", "--force", wt], { allowFail: true });
        if (r.code !== 0 && fs.existsSync(wt)) fs.rmSync(wt, { recursive: true, force: true });
      }
      await this.git(repo, ["worktree", "prune"], { allowFail: true });
      let deleted = false;
      if (deleteRef && branch && (await this.refExists(repo, branch))) {
        const main = await this.currentBranch(repo);
        if (branch !== main) {
          await this.git(repo, ["branch", "-D", branch]);
          deleted = true;
        }
      }
      return { ok: true, deletedRef: deleted };
    });
  }

  async renameBranch(slug, { from, to }) {
    if (!REF_RE.test(from || "")) throw new GitError(400, "Invalid branch");
    if (!BRANCH_RE.test(to || "") || to.length > 60) throw new GitError(400, "Invalid branch name");
    return this.lock(slug, async () => {
      const repo = this.dirFor(slug, null);
      if (!(await this.refExists(repo, from))) throw new GitError(404, `Branch '${from}' not found`);
      if (await this.refExists(repo, to)) throw new GitError(409, `Branch '${to}' already exists`);
      await this.git(repo, ["branch", "-m", from, to]);
      return { ok: true };
    });
  }

  // ---------------------------------------------------------------- checkpoints

  /** Commit everything in the worktree (or main). Skips if HEAD is not on the expected branch. */
  async checkpoint(slug, { worktree, message, expectBranch }) {
    if (worktree != null && !WORKTREE_RE.test(worktree)) throw new GitError(400, "Invalid worktree");
    if (expectBranch != null && !REF_RE.test(expectBranch)) throw new GitError(400, "Invalid branch");
    const msg = String(message || "nxeon: checkpoint").replace(/\0/g, "").slice(0, 2000);
    return this.lock(slug, () => this._checkpoint(this.dirFor(slug, worktree || null), msg, expectBranch));
  }
  async _checkpoint(dir, message, expectBranch) {
    const cur = await this.currentBranch(dir);
    if (!cur) return { sha: null, skipped: "detached_head" };
    if (expectBranch && cur !== expectBranch) return { sha: null, skipped: "head_moved", branch: cur };
    for (let attempt = 0; ; attempt++) {
      try {
        await this.git(dir, ["add", "-A"]);
        const diff = await this.git(dir, ["diff", "--cached", "--quiet"], { allowFail: true });
        if (diff.code === 0) return { sha: null, files: 0 };
        const c = await this.git(dir, ["commit", "-q", "--no-verify", "-m", message], { allowFail: true });
        if (c.code !== 0) {
          if (/unmerged|conflict/i.test(c.stderr + c.stdout)) return { sha: null, skipped: "unmerged" };
          throw new GitError(500, `commit failed: ${(c.stderr || c.stdout).trim().slice(0, 300)}`);
        }
        const sha = await this.headSha(dir);
        const st = await this.git(dir, ["show", "--shortstat", "--format=", "HEAD"], { allowFail: true });
        return { sha, files: parseShortstat(st.stdout).files };
      } catch (err) {
        // another git process (e.g. Claude) holds index.lock: retry briefly
        if (attempt < 3 && /index\.lock/.test(err.message)) {
          await new Promise((r) => setTimeout(r, 400 * (attempt + 1)));
          continue;
        }
        throw err;
      }
    }
  }

  // ---------------------------------------------------------------- inspection

  /** Diff of the working tree (incl. untracked, excl. ignored) vs the merge-base with `base`. */
  async _workingDiff(dir, base) {
    const mb = await this.git(dir, ["merge-base", "HEAD", base], { allowFail: true });
    const mergeBase = mb.code === 0 ? mb.stdout.trim() : null;
    const against = mergeBase || (await this.headSha(dir));
    const tmpIndex = path.join(os.tmpdir(), `nxeon-idx-${process.pid}-${crypto.randomBytes(6).toString("hex")}`);
    try {
      const real = (await this.git(dir, ["rev-parse", "--path-format=absolute", "--git-path", "index"])).stdout.trim();
      try {
        fs.copyFileSync(real, tmpIndex);
      } catch {
        await this.git(dir, ["read-tree", "HEAD"], { env: { GIT_INDEX_FILE: tmpIndex } });
      }
      const env = { GIT_INDEX_FILE: tmpIndex };
      await this.git(dir, ["add", "-A"], { env });
      const num = await this.git(dir, ["diff", "--cached", "--numstat", "--no-renames", "-z", against], { env });
      const ns = await this.git(dir, ["diff", "--cached", "--name-status", "--no-renames", "-z", against], { env });
      const status = new Map();
      const parts = ns.stdout.split("\0");
      for (let i = 0; i + 1 < parts.length; i += 2) if (parts[i]) status.set(parts[i + 1], parts[i][0]);
      const files = [];
      for (const rec of num.stdout.split("\0")) {
        if (!rec) continue;
        const m = /^(-|\d+)\t(-|\d+)\t(.*)$/s.exec(rec);
        if (!m) continue;
        const binary = m[1] === "-";
        files.push({
          path: m[3],
          status: { A: "added", D: "deleted", M: "modified", T: "modified" }[status.get(m[3])] || "modified",
          additions: binary ? 0 : Number(m[1]),
          deletions: binary ? 0 : Number(m[2]),
          binary,
        });
      }
      files.sort((a, b) => a.path.localeCompare(b.path));
      return { mergeBase: against, files };
    } finally {
      fs.rm(tmpIndex, { force: true }, () => {});
    }
  }

  async diff(slug, { worktree, base }) {
    if (worktree != null && !WORKTREE_RE.test(worktree)) throw new GitError(400, "Invalid worktree");
    if (!REF_RE.test(base || "")) throw new GitError(400, "Invalid base");
    return this.lock(slug, async () => {
      const dir = this.dirFor(slug, worktree || null);
      const { mergeBase, files } = await this._workingDiff(dir, base);
      const totals = files.reduce((a, f) => ({ additions: a.additions + f.additions, deletions: a.deletions + f.deletions }), { additions: 0, deletions: 0 });
      return { base, mergeBase, head: await this.headSha(dir), files, ...totals };
    });
  }

  async fileDiff(slug, { worktree, base, path: p }) {
    if (worktree != null && !WORKTREE_RE.test(worktree)) throw new GitError(400, "Invalid worktree");
    if (!REF_RE.test(base || "")) throw new GitError(400, "Invalid base");
    const rel = cleanRelPath(p);
    return this.lock(slug, async () => {
      const dir = this.dirFor(slug, worktree || null);
      const mb = await this.git(dir, ["merge-base", "HEAD", base], { allowFail: true });
      const against = mb.code === 0 ? mb.stdout.trim() : await this.headSha(dir);
      const show = await this.git(dir, ["show", `${against}:${rel}`], { allowFail: true, encoding: "buffer" });
      const orig = show.code === 0 ? show.stdout : null;
      const abs = path.resolve(dir, rel);
      let mod = null;
      if (isInside(dir, abs)) {
        try {
          const st = fs.lstatSync(abs);
          if (st.isFile()) mod = st.size > MAX_FILE ? Buffer.alloc(0) : fs.readFileSync(abs);
        } catch {
          /* deleted */
        }
      }
      const binary = (orig && looksBinary(orig)) || (mod && looksBinary(mod)) || false;
      const tooLarge = (orig && orig.length > MAX_FILE) || false;
      const patch = await this.git(dir, ["diff", "--no-color", against, "--", rel], { allowFail: true });
      return {
        path: rel,
        status: orig == null ? "added" : mod == null ? "deleted" : "modified",
        binary,
        original: binary || tooLarge || orig == null ? "" : orig.toString("utf8"),
        modified: binary || mod == null ? "" : mod.toString("utf8"),
        patch: binary ? "" : patch.stdout.slice(0, 512 * 1024),
      };
    });
  }

  /** Per-branch summary: ahead/behind vs base and changed files (incl. uncommitted). */
  async status(slug, { branches }) {
    if (!Array.isArray(branches) || branches.length > 200) throw new GitError(400, "Invalid branches");
    return this.lock(slug, async () => {
      const repo = this.dirFor(slug, null);
      const mainBranch = await this.currentBranch(repo);
      const mainDirty = (await this.git(repo, ["status", "--porcelain", "-uall"], { allowFail: true })).stdout.trim().length > 0;
      const out = [];
      for (const b of branches) {
        if (!b || !WORKTREE_RE.test(b.worktree || "") || !REF_RE.test(b.base || "")) continue;
        const dir = this.worktreeDir(slug, b.worktree);
        if (!fs.existsSync(dir)) {
          out.push({ worktree: b.worktree, missing: true });
          continue;
        }
        try {
          const lr = await this.git(dir, ["rev-list", "--left-right", "--count", `${b.base}...HEAD`], { allowFail: true });
          const [behind, ahead] = lr.code === 0 ? lr.stdout.trim().split(/\s+/).map(Number) : [0, 0];
          const { files } = await this._workingDiff(dir, b.base);
          const dirty = (await this.git(dir, ["status", "--porcelain"], { allowFail: true })).stdout.trim().length > 0;
          out.push({ worktree: b.worktree, ahead: ahead || 0, behind: behind || 0, filesChanged: files.length, dirty, head: await this.headSha(dir) });
        } catch (err) {
          out.push({ worktree: b.worktree, error: err.message });
        }
      }
      return { mainBranch, mainDirty, branches: out };
    });
  }

  async history(slug, { worktree, limit = 50 }) {
    if (worktree != null && !WORKTREE_RE.test(worktree)) throw new GitError(400, "Invalid worktree");
    const n = Math.max(1, Math.min(200, Number(limit) || 50));
    return this.lock(slug, async () => {
      const dir = this.dirFor(slug, worktree || null);
      if (!(await this.headSha(dir))) return { commits: [], dirty: false };
      const r = await this.git(dir, ["log", `-n${n}`, "--format=%x1e%H%x1f%P%x1f%ct%x1f%an%x1f%s", "--shortstat"]);
      const commits = [];
      for (const rec of r.stdout.split("\x1e")) {
        if (!rec.trim()) continue;
        const [head, ...rest] = rec.split("\n");
        const [sha, parents, ct, author, subject] = head.split("\x1f");
        const st = parseShortstat(rest.join("\n"));
        commits.push({
          sha, parents: parents ? parents.split(" ").filter(Boolean) : [], time: Number(ct) * 1000, author, message: subject,
          filesChanged: st.files, insertions: st.insertions, deletions: st.deletions,
        });
      }
      const dirty = (await this.git(dir, ["status", "--porcelain"], { allowFail: true })).stdout.trim().length > 0;
      return { commits, dirty, branch: await this.currentBranch(dir) };
    });
  }

  // ---------------------------------------------------------------- merge / revert

  /** Merge `branch` into the main branch (in the repo dir) with --no-ff; never leaves a conflicted tree. */
  async merge(slug, { branch, worktree, into, message }) {
    if (!REF_RE.test(branch || "") || !REF_RE.test(into || "")) throw new GitError(400, "Invalid branch");
    if (worktree != null && !WORKTREE_RE.test(worktree)) throw new GitError(400, "Invalid worktree");
    return this.lock(slug, async () => {
      const repo = this.dirFor(slug, null);
      const cur = await this.currentBranch(repo);
      if (cur !== into) throw new GitError(409, `Main checkout is on '${cur || "detached HEAD"}', expected '${into}'`, { code: "main_head_moved" });
      if (worktree) await this._checkpoint(this.dirFor(slug, worktree), `nxeon: checkpoint before merge into ${into}`, branch);
      await this._checkpoint(repo, `nxeon: checkpoint before merging ${branch}`, into);
      if (!(await this.refExists(repo, branch))) throw new GitError(404, `Branch '${branch}' not found`);
      // dry run first (git >= 2.38): detect conflicts without touching the working tree
      const dry = await this.git(repo, ["merge-tree", "--write-tree", "--name-only", "--no-messages", into, branch], { allowFail: true });
      if (dry.code === 1) {
        const lines = dry.stdout.split("\n").map((l) => l.trim()).filter(Boolean);
        return { ok: false, conflicts: [...new Set(lines.slice(1))] };
      }
      const behind = await this.git(repo, ["rev-list", "--count", `${into}..${branch}`]);
      if (Number(behind.stdout.trim()) === 0) return { ok: true, sha: await this.headSha(repo), upToDate: true };
      const msg = String(message || `nxeon: merge ${branch} into ${into}`).slice(0, 500);
      const r = await this.git(repo, ["merge", "--no-ff", "--no-edit", "-m", msg, branch], { allowFail: true });
      if (r.code !== 0) {
        const u = await this.git(repo, ["diff", "--name-only", "--diff-filter=U"], { allowFail: true });
        const conflicts = u.stdout.split("\n").map((l) => l.trim()).filter(Boolean);
        await this.git(repo, ["merge", "--abort"], { allowFail: true });
        if (conflicts.length) return { ok: false, conflicts };
        throw new GitError(500, `merge failed: ${(r.stderr || r.stdout).trim().slice(0, 300)}`);
      }
      return { ok: true, sha: await this.headSha(repo) };
    });
  }

  /** `git revert --no-edit <sha>` in main or a worktree (pending changes are checkpointed first). */
  async revert(slug, { worktree, sha, expectBranch }) {
    if (!SHA_RE.test(sha || "")) throw new GitError(400, "Invalid sha");
    if (worktree != null && !WORKTREE_RE.test(worktree)) throw new GitError(400, "Invalid worktree");
    return this.lock(slug, async () => {
      const dir = this.dirFor(slug, worktree || null);
      const ok = await this.git(dir, ["merge-base", "--is-ancestor", sha, "HEAD"], { allowFail: true });
      if (ok.code !== 0) throw new GitError(404, "Commit is not part of this branch's history");
      const parents = (await this.git(dir, ["rev-list", "--parents", "-n1", sha])).stdout.trim().split(" ").slice(1);
      if (parents.length === 0) throw new GitError(400, "Cannot undo the initial snapshot");
      if (parents.length > 1) throw new GitError(400, "Cannot undo a merge commit from here");
      const pre = await this._checkpoint(dir, "nxeon: checkpoint before undo", expectBranch);
      if (pre.skipped && pre.skipped !== "unmerged") throw new GitError(409, `Cannot undo: ${pre.skipped}`);
      const r = await this.git(dir, ["revert", "--no-edit", sha], { allowFail: true });
      if (r.code !== 0) {
        const u = await this.git(dir, ["diff", "--name-only", "--diff-filter=U"], { allowFail: true });
        const conflicts = u.stdout.split("\n").map((l) => l.trim()).filter(Boolean);
        await this.git(dir, ["revert", "--abort"], { allowFail: true });
        if (conflicts.length) return { ok: false, conflicts, checkpoint: pre.sha || null };
        if (/nothing to commit|empty/i.test(r.stderr + r.stdout)) return { ok: true, sha: null, empty: true, checkpoint: pre.sha || null };
        throw new GitError(500, `revert failed: ${(r.stderr || r.stdout).trim().slice(0, 300)}`);
      }
      return { ok: true, sha: await this.headSha(dir), checkpoint: pre.sha || null };
    });
  }
}

function parseShortstat(s) {
  const f = /(\d+) files? changed/.exec(s);
  const i = /(\d+) insertions?\(\+\)/.exec(s);
  const d = /(\d+) deletions?\(-\)/.exec(s);
  return { files: f ? Number(f[1]) : 0, insertions: i ? Number(i[1]) : 0, deletions: d ? Number(d[1]) : 0 };
}

/** HTTP dispatcher shared by server.js and the app's test fake: POST /v2/git/<op> with a JSON body. */
async function handleGit(git, op, body) {
  if (!body || typeof body !== "object") throw new GitError(400, "Body must be a JSON object");
  const slug = body.projectSlug;
  if (typeof slug !== "string" || !SLUG_RE.test(slug)) throw new GitError(400, "Invalid projectSlug");
  switch (op) {
    case "ensure":
      return git.ensure(slug);
    case "branch/create":
      return git.createBranch(slug, body);
    case "branch/remove":
      return git.removeBranch(slug, body);
    case "branch/rename":
      return git.renameBranch(slug, body);
    case "checkpoint":
      return git.checkpoint(slug, body);
    case "diff":
      return git.diff(slug, body);
    case "file-diff":
      return git.fileDiff(slug, body);
    case "status":
      return git.status(slug, body);
    case "history":
      return git.history(slug, body);
    case "merge":
      return git.merge(slug, body);
    case "revert":
      return git.revert(slug, body);
    default:
      throw new GitError(404, "Unknown git operation");
  }
}

module.exports = { GitManager, GitError, handleGit, BRANCH_RE, WORKTREE_RE, REF_RE, SLUG_RE, GITIGNORE };

import Database from 'better-sqlite3';
import fs from 'node:fs';
import path from 'node:path';

export type DB = Database.Database;

// Timestamps are stored as integer epoch milliseconds; DTOs convert to ISO strings.
const MIGRATIONS: string[] = [
  `
  CREATE TABLE users (
    id TEXT PRIMARY KEY,
