}

/** Projects visible to the user (admins: all). Members of a parent also see its sub-projects (inherited role). */
export function visibleProjects(ctx: Ctx, user: UserRow, includeArchived: boolean): { p: ProjectRow; role: EffectiveRole }[] {
  const arch = includeArchived ? '' : 'AND p.archived = 0';
  if (user.role === 'admin') {
    return (ctx.db.prepare(`SELECT p.* FROM projects p WHERE 1=1 ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`).all() as ProjectRow[]).map(
      (p) => ({ p, role: 'admin' as const }),
    );
  }
  return (
    ctx.db
      .prepare(
        `SELECT p.*, m.role AS member_role, pm.role AS parent_role FROM projects p
         LEFT JOIN project_members m ON m.project_id = p.id AND m.user_id = ?
         LEFT JOIN project_members pm ON p.parent_id IS NOT NULL AND pm.project_id = p.parent_id AND pm.user_id = ?
         WHERE (m.role IS NOT NULL OR pm.role IS NOT NULL) ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`,
      )
      .all(user.id, user.id) as (ProjectRow & { member_role: ProjectRole | null; parent_role: ProjectRole | null })[]
  ).map((p) => ({ p, role: maxRole(p.member_role, p.parent_role)! }));
}

/** Background: refresh cached ahead/behind/changed-files of branches whose stats are older than a minute. */
const statsInFlight = new Set<string>();
function refreshBranchStats(ctx: Ctx, rows: BranchRow[], projects: Map<string, ProjectRow>) {
  const stale = new Map<string, BranchRow[]>();
  for (const b of rows) {
    if (b.stat_at && now() - b.stat_at < 60_000) continue;
    if (statsInFlight.has(b.project_id)) continue;
    const arr = stale.get(b.project_id) ?? [];
    arr.push(b);
    stale.set(b.project_id, arr);
  }
  for (const [pid, list] of stale) {
    const p = projects.get(pid);
    if (!p) continue;
    statsInFlight.add(pid);
    void (async () => {
      try {
        const main = p.git_main ?? 'main';
        const r = await ctx.cb.git<{ branches: { worktree: string; ahead?: number; behind?: number; filesChanged?: number }[] }>('status', {
          projectSlug: p.slug, branches: list.map((b) => ({ worktree: b.dir, base: rows.some((x) => x.project_id === pid && x.name === b.base) || b.base === main ? b.base : main })),
        }, 20_000);
        const upd = ctx.db.prepare(`UPDATE branches SET ahead = ?, behind = ?, files_changed = ?, stat_at = ? WHERE project_id = ? AND dir = ? AND status = 'active'`);
        for (const x of r.branches ?? []) if (x.filesChanged != null) upd.run(x.ahead ?? 0, x.behind ?? 0, x.filesChanged, now(), pid, x.worktree);
      } catch {
        /* claudebox busy/down */
      } finally {
        statsInFlight.delete(pid);
      }
    })();
  }
}

/** Stop previews, abort runs, drop the DB rows and move the files (incl. branch worktrees) to .trash. */
export async function deleteProject(ctx: Ctx, project: ProjectRow) {
  const { db, cfg } = ctx;
  const active = db.prepare(`SELECT id FROM runs WHERE project_id = ? AND status IN ('queued','running')`).all(project.id) as { id: string }[];
  for (const r of active) await ctx.runs.abort(r.id);

// Git branches (worktrees) + preview keys + port allocation. Git itself runs in claudebox (/v2/git/*).
import crypto from 'node:crypto';
import path from 'node:path';
import type { ProjectRow } from '../auth.js';
import { ClaudeboxError } from '../claudebox.js';
import type { Config } from '../config.js';
import type { Ctx } from '../ctx.js';
import type { DB } from '../db.js';
import { iso } from '../db.js';
import { badRequest, conflict, HttpError, notFound } from './errors.js';

/** Lowercase segments joined by single '-' or '/'. Never contains '--' (the preview-key separator). */
export const BRANCH_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*(?:\/[a-z0-9]+(?:-[a-z0-9]+)*)*$/;
export const BRANCH_MAX = 40;
const RESERVED = new Set(['main', 'master', 'head']);

export interface BranchRow {
  id: string;
  project_id: string;
  name: string;
  dir: string;
  base: string;
  preview_port: number;
  status: 'active' | 'merged' | 'discarded';
  created_by: string | null;
  created_at: number;
  closed_at: number | null;
  merged_sha: string | null;
  files_changed: number | null;
  ahead: number | null;
  behind: number | null;
  stat_at: number | null;
}

export function validBranchName(name: string, project?: Pick<ProjectRow, 'git_main'>): string | null {
  if (!name || name.length > BRANCH_MAX) return `Branch names are 1-${BRANCH_MAX} characters`;
  if (!BRANCH_RE.test(name)) return 'Use lowercase letters, digits, single dashes and "/" (e.g. feature/login)';
  if (RESERVED.has(name) || name === project?.git_main) return `"${name}" is reserved`;
  return null;
}

/** Worktree directory name (stable for the branch's lifetime): '/' → '_'. */
export function worktreeDirName(name: string): string {
  return name.replace(/\//g, '_').slice(0, 64);
}

/** Preview key used in /preview/<key>/ and BASE_PATH: <slug> for main, <slug>--<dir> for branches. */
export function previewKey(slug: string, b?: Pick<BranchRow, 'dir'> | null): string {
  return b ? `${slug}--${b.dir}` : slug;
}
export function previewPath(slug: string, b?: Pick<BranchRow, 'dir'> | null): string {
  return `/preview/${previewKey(slug, b)}/`;
}

export function worktreePath(cfg: Config, slug: string, dir: string): string {
  return path.join(cfg.projectsDir, '.branches', slug, dir);
}
export function branchesRoot(cfg: Config, slug: string): string {
  return path.join(cfg.projectsDir, '.branches', slug);
}
/** cwd as seen by Claude inside claudebox. */
export function claudeboxCwd(cfg: Config, slug: string, b?: Pick<BranchRow, 'dir'> | null): string {
  return b ? `${cfg.claudeboxProjectsDir}/.branches/${slug}/${b.dir}` : `${cfg.claudeboxProjectsDir}/${slug}`;
}

export function getBranch(db: DB, projectId: string, name: string): BranchRow | null {
  return (db.prepare(`SELECT * FROM branches WHERE project_id = ? AND name = ? AND status = 'active'`).get(projectId, name) as BranchRow | undefined) ?? null;
}
export function activeBranches(db: DB, projectId: string): BranchRow[] {
  return db.prepare(`SELECT * FROM branches WHERE project_id = ? AND status = 'active' ORDER BY created_at`).all(projectId) as BranchRow[];
}

/** `?branch=` → active branch row, or null for main ('' / 'main' / the repo's main branch name). 404 if unknown. */
export function branchParam(db: DB, project: ProjectRow, raw: unknown): BranchRow | null {
  if (raw == null || raw === '' || raw === 'main' || (typeof raw === 'string' && raw === project.git_main)) return null;
  if (typeof raw !== 'string' || raw.length > 100) throw badRequest('Invalid branch');
  const b = getBranch(db, project.id, raw);
  if (!b) throw notFound(`Branch "${raw}" not found`);
  return b;
}

/** Active (queued/running) runs on main (branch = null) or a branch of a project. */
export function activeRunCount(db: DB, projectId: string, branch: string | null): number {
  return (db
    .prepare(`SELECT COUNT(*) AS n FROM runs WHERE project_id = ? AND status IN ('queued','running') AND branch IS ?`)
    .get(projectId, branch) as { n: number }).n;
}

export function allocatePort(ctx: Pick<Ctx, 'db' | 'cfg'>): number {
  const used = new Set<number>([
    ...(ctx.db.prepare(`SELECT preview_port AS p FROM projects`).all() as { p: number }[]).map((r) => r.p),
    ...(ctx.db.prepare(`SELECT preview_port AS p FROM branches WHERE status = 'active'`).all() as { p: number }[]).map((r) => r.p),
  ]);
  for (let p = ctx.cfg.previewPortMin; p <= ctx.cfg.previewPortMax; p++) if (!used.has(p)) return p;
  throw conflict('No free preview ports left (all 100 are allocated). Delete a project or close a branch first.', 'no_ports');
}

export function branchDTO(b: BranchRow, project: Pick<ProjectRow, 'slug'>, live?: { ahead?: number; behind?: number; filesChanged?: number; dirty?: boolean } | null) {
  return {
    id: b.id,
    name: b.name,
    base: b.base,
    status: b.status,
    previewPort: b.preview_port,
    previewPath: previewPath(project.slug, b),
    createdBy: b.created_by,
    createdAt: iso(b.created_at)!,
    closedAt: iso(b.closed_at),
    mergedSha: b.merged_sha,
    ahead: live?.ahead ?? b.ahead,
    behind: live?.behind ?? b.behind,
    filesChanged: live?.filesChanged ?? b.files_changed,
    dirty: live?.dirty ?? null,
  };
}

/** Map a claudebox git error onto an HttpError (keeps 4xx semantics). */
export function gitError(err: unknown): HttpError {
  if (err instanceof HttpError) return err;
  if (err instanceof ClaudeboxError) {
    const body = (err.body ?? {}) as { code?: string };
    if (err.statusCode === 404) return new HttpError(404, body.code ?? 'git_not_found', err.message);
    if (err.statusCode === 409) return new HttpError(409, body.code ?? 'git_conflict', err.message);
    if (err.statusCode === 400) return new HttpError(400, body.code ?? 'git_invalid', err.message);
    return new HttpError(502, 'git_failed', err.message);
  }
  return new HttpError(502, 'git_failed', (err as Error)?.message ?? 'git failed');
}

