// Per-project sandbox identities (claudebox SANDBOX_MODE=strict). The app is authoritative: it maps
// projects to uids and decides which projects a run may access; claudebox only validates ranges/paths.
import type { DB } from '../db.js';

/** Project sandbox uid == gid == SANDBOX_BASE + projects.sandbox_id (20001-29999). */
export const SANDBOX_BASE = 20000;
export const SANDBOX_MAX_ID = 9999;
/** Per-user identities for future multi-project ("Nexus") runs: NEXUS_BASE + n (30000-39999). */
export const NEXUS_BASE = 30000;
export const SANDBOX_HOMES = '/workspace/.sandbox-homes';

export interface SandboxSpec {
  uid: number;
  gid: number;
  /** supplementary groups (project gids the process may access); always includes gid */
  groups: number[];
  home: string;
}

export function projectSandbox(p: { sandbox_id: number | null }): SandboxSpec | null {
  if (p.sandbox_id == null || !(p.sandbox_id >= 1 && p.sandbox_id <= SANDBOX_MAX_ID)) return null;
  const uid = SANDBOX_BASE + p.sandbox_id;
  return { uid, gid: uid, groups: [uid], home: `${SANDBOX_HOMES}/${uid}` };
}

/**
 * Spec for a run that may access several projects (Nexus Chat): own identity + the projects' gids.
 * `identityUid` must be in 30000-39999; callers compute `projects` from the user's permissions.
 */
export function multiProjectSandbox(identityUid: number, projects: { sandbox_id: number | null }[]): SandboxSpec {
  if (!(identityUid > NEXUS_BASE && identityUid <= NEXUS_BASE + 9999)) throw new Error('invalid Nexus identity uid');
  const groups = [identityUid];
  for (const p of projects) {
    const s = projectSandbox(p);
    if (s && !groups.includes(s.gid)) groups.push(s.gid);
  }
  return { uid: identityUid, gid: identityUid, groups, home: `${SANDBOX_HOMES}/${identityUid}` };
}

/**
 * Next sandbox id: monotonic, never reused (a deleted project's home may still hold its sessions/caches).
 * Must run inside the project-creating transaction.
 */
export function nextSandboxId(db: DB): number {
  const maxRow = (db.prepare(`SELECT COALESCE(MAX(sandbox_id), 0) AS m FROM projects`).get() as { m: number }).m;
  const seqRow = db.prepare(`SELECT value FROM settings WHERE key = 'sandbox_seq'`).get() as { value: string } | undefined;
  const seq = seqRow ? Number(JSON.parse(seqRow.value)) || 0 : 0;
  const id = Math.max(maxRow, seq) + 1;
  if (id > SANDBOX_MAX_ID) throw new Error('No sandbox ids left');
  db.prepare(`INSERT INTO settings(key, value) VALUES ('sandbox_seq', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`).run(JSON.stringify(id));
  return id;
}
EOF
