  let a: any, b: any;

  it('assigns unique, monotonic sandbox ids that are never reused', async () => {
    a = (await api(env, admin, 'POST', '/api/projects', { name: 'Sandbox A' })).json;
    b = (await api(env, admin, 'POST', '/api/projects', { name: 'Sandbox B' })).json;
    const ia = sandboxId(a.id);
    const ib = sandboxId(b.id);
    expect(ia).toBeGreaterThan(0);
    expect(ib).toBe(ia + 1);
    const c = (await api(env, admin, 'POST', '/api/projects', { name: 'Sandbox C' })).json;
    const ic = sandboxId(c.id);
    expect((await api(env, admin, 'DELETE', `/api/projects/${c.id}`)).status).toBe(200);
    const d = (await api(env, admin, 'POST', '/api/projects', { name: 'Sandbox D' })).json;
    expect(sandboxId(d.id)).toBe(ic + 1); // C's id (and its home) is not handed to D
