#!/bin/bash
# Test double for `sudo -n /usr/local/sbin/nx-sandbox <op> ...`: performs the same argument/env-file
# protocol WITHOUT switching uid, and logs every helper call to $FAKE_SUDO_LOG (one JSON-ish line each).
set -u
