        --gid|--groups|--setenv) shift 2 ;;
        --cwd) cwd=$2; shift 2 ;;
        --env-file) envfile=$2; shift 2 ;;
        --) shift; break ;;
        *) echo "fake-sudo: bad arg $1" >&2; exit 2 ;;
      esac
