    ;;
  kill)
    pgid="" sig=TERM
    while [ $# -gt 0 ]; do case "$1" in --pgid) pgid=$2; shift 2 ;; --signal) sig=$2; shift 2 ;; *) shift 2 ;; esac; done
    kill -s "$sig" -- "-$pgid" 2>/dev/null || true
    ;;
  kill-port) echo 0 ;;
  setup|home) echo '{"ok":true,"heavy":false}' ;;
  fixperms|net-claim) echo ok ;;
  *) echo "fake-sudo: unknown op $op" >&2; exit 2 ;;
esac
EOF
