"use strict";
// Sandbox plumbing tests. Real uid switching needs root + /usr/local/sbin/nx-sandbox (see
// sandbox/redteam.sh for the in-container checks); here a fake `sudo` (test/fake-sudo.sh) speaks the same
// helper protocol without changing uid, so argv/env-file/stdin/attachment handling is verified end to end.
const assert = require("node:assert/strict");
const test = require("node:test");
const fs = require("fs");
const os = require("os");
const path = require("path");

const { Sandbox, ENV_DROP } = require("../lib/sandbox");
const { RunManager, buildRunArgs } = require("../lib/runs");
const { PreviewManager } = require("../lib/preview");

const MOCK = path.join(__dirname, "mock-claude.js");
const FAKE_SUDO = path.join(__dirname, "fake-sudo.sh");
fs.chmodSync(MOCK, 0o755);
fs.chmodSync(FAKE_SUDO, 0o755);

const TMP = fs.mkdtempSync(path.join(os.tmpdir(), "claudebox-sandbox-"));
const PROJECTS = path.join(TMP, "projects");
const HOMES = path.join(TMP, "homes");
const UPLOADS = path.join(TMP, "private", "uploads");
const ENVDIR = path.join(TMP, "envs");
const LOG = path.join(TMP, "helper.log");
const ARGS_FILE = path.join(TMP, "args.json");
for (const d of [path.join(PROJECTS, "alpha"), path.join(UPLOADS, "up1"), HOMES]) fs.mkdirSync(d, { recursive: true });
fs.writeFileSync(path.join(UPLOADS, "up1", "notes.txt"), "secret notes");
process.env.FAKE_HOMES = HOMES;
process.env.FAKE_SUDO_LOG = LOG;

const sb = new Sandbox({ mode: "strict", sudo: FAKE_SUDO, wrapper: "/usr/bin/env", projectsDir: PROJECTS, homesDir: HOMES, envDir: ENVDIR, nexusDir: path.join(TMP, "nexus") });
const SPEC = { uid: 20007, gid: 20007, groups: [20007], home: path.join(HOMES, "20007") };
fs.mkdirSync(SPEC.home, { recursive: true });

const helperLog = () => (fs.existsSync(LOG) ? fs.readFileSync(LOG, "utf8") : "");
const waitFor = async (fn, ms = 8000) => {
  const end = Date.now() + ms;
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() > end) throw new Error("timeout");
    await new Promise((r) => setTimeout(r, 25));
  }
};

